/** All translations for zizhitongjian ch.160 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "資治通鑑 第160卷卷第一百六十", literal: "Comprehensive Mirror in Aid of Governance, Volume 160, the one hundred and sixtieth scroll", idiomatic: "Comprehensive Mirror in Aid of Governance, Volume 160" },
  { zh: "【梁紀十六】　強圉單閼，一年。", literal: "[Liang Records 16] Qiangyu Danqian; one year in all.", idiomatic: "[Liang Records 16] Qiangyu Danqian—one year in all." },
  { zh: "高祖武皇帝十六太清元年（", literal: "Great Ancestor Emperor Wu, sixteenth year of the Taqing era (", idiomatic: "Emperor Wu of Liang, sixteenth year of Taqing (" },
  { zh: "丁卯，公元五四七年）", literal: "dingmao, 547 CE)", idiomatic: "dingmao, AD 547)" },
  { zh: "春，正月朔，日有食之，不盡如鉤。", literal: "In spring, on the first day of the first month, there was an eclipse of the sun, not complete—like a hook.", idiomatic: "In spring, on new year's day, the sun was eclipsed, leaving a hook of light." },
  { zh: "壬寅，荊州刺史廬陵威王續卒。", literal: "On renyin, Jingzhou Inspector Prince of Luling, Wei Xu, died.", idiomatic: "On renyin, Prince Wei Xu of Luling, Jingzhou inspector, died." },
  { zh: "以湘東王繹為都督荊、雍等九州諸軍事、荊州刺史。", literal: "Prince of Xiangdong Yi was made Commander-in-Chief of military affairs in Jing, Yong, and eight other provinces, and Jingzhou Inspector.", idiomatic: "Prince Xiao Yi of Xiangdong was made commander of military affairs in Jing, Yong, and eight other provinces, and Jingzhou inspector." },
  { zh: "續素貪婪，臨終，有啟遣中錄事參軍謝宣融獻金銀器千餘件，上方知其富，因問宣融曰：「王之金盡此乎？", literal: "Xu had always been greedy; at death's door he had a memorial sent by Central Recorder Staff Officer Xie Xuanrong presenting more than a thousand pieces of gold and silver vessels. The emperor already knew his wealth and therefore asked Xuanrong: \"Are the Prince's gold and silver all here?", idiomatic: "Xu had always been greedy. At death's door he sent a memorial through Central Recorder staff officer Xie Xuanrong offering more than a thousand gold and silver vessels. The emperor already knew how rich he was and asked Xuanrong: \"Is this all the prince's gold?\"" },
  { zh: "」宣融曰：「此之謂多，安可加也！", literal: "\" Xuanrong said: \"This is what is called much—how could there be more!", idiomatic: "\" Xuanrong said: \"You call this much—how could there be more!\"" },
  { zh: "大王之過如日月之食，欲令陛下知之，故終而不隱。", literal: "The great prince's faults are like an eclipse of sun or moon; he wished Your Majesty to know, and therefore at the end he did not conceal them.", idiomatic: "The prince's faults are like an eclipse of sun or moon; he wished Your Majesty to know, and so at the end he did not hide them." },
  { zh: "」上意乃解。", literal: "\" The emperor's mind was then eased.", idiomatic: "\" The emperor's anger eased." },
  { zh: "初，湘東王繹為荊州刺史，有微過，續代之，以狀聞，自此二王不通書問。", literal: "Earlier, Prince of Xiangdong Yi had been Jingzhou Inspector and had minor faults; Xu replaced him and reported the facts upward; from then the two princes did not exchange letters.", idiomatic: "Earlier, Prince Xiao Yi of Xiangdong had been Jingzhou inspector and committed minor faults; Xu replaced him and reported it to the throne; from then the two princes exchanged no letters." },
  { zh: "繹聞其死，入閣而躍，屜為之破。", literal: "When Yi heard of his death, he entered the side chamber and leaped; his slippers were broken by it.", idiomatic: "When Yi heard of his death, he went into the side chamber and leaped for joy until his slippers split." },
  { zh: "丙午，東魏勃海獻武王歡卒。", literal: "On bingwu, Eastern Wei Prince of Bohai, King Xianwu Huan, died.", idiomatic: "On bingwu, Gao Huan, Eastern Wei's Prince of Bohai and King Xianwu, died." },
  { zh: "歡性深密，終日儼然，人不能測，機權之際，變化若神。", literal: "Huan's nature was deep and secret; all day he was stern and grave; men could not fathom him; at moments of stratagem and power his changes were like a god's.", idiomatic: "Gao Huan was deep and inscrutable—stern all day, impossible to read; at the hinge of power his shifts were godlike." },
  { zh: "制馭軍旅，法令嚴肅。", literal: "In controlling armies, laws and orders were strict and solemn.", idiomatic: "He commanded armies with strict law and order." },
  { zh: "聽斷明察，不可欺犯。", literal: "In hearing and deciding cases he was bright and penetrating; none could deceive or offend him.", idiomatic: "In judgment he was sharp; none could deceive him." },
  { zh: "擢人受任，在於得才，苟其所堪，無問廝養；", literal: "In promoting men and assigning office, what mattered was gaining talent; if they could bear the task, he asked not whether they had been stable boys;", idiomatic: "He promoted by talent alone; if a man could do the work, he cared nothing whether he had been a stable boy;" },
  { zh: "有虛聲無實者，皆不任用。", literal: "those with empty fame and no substance he never employed.", idiomatic: "men of empty fame he never used." },
  { zh: "雅尚儉素，刀劍鞍勒無金玉之飾。", literal: "He esteemed frugality and simplicity; swords, saddles, and bridles had no gold or jade ornament.", idiomatic: "He loved plain living—no gold or jade on sword, saddle, or bridle." },
  { zh: "少能劇飲，自當大任，不過三爵。", literal: "In youth he could drink heavily; once he bore great responsibility, he took no more than three cups.", idiomatic: "In youth he could drink hard; once he bore great power, he stopped at three cups." },
  { zh: "知人好士，全護勳舊；", literal: "He knew men and loved scholars, fully protecting meritorious elders;", idiomatic: "He knew men, loved scholars, and shielded old merit;" },
  { zh: "每獲敵國盡節之臣，多不之罪。", literal: "whenever he captured ministers of the enemy who had died for their state, he mostly did not punish them.", idiomatic: "when he took enemy ministers who had died for their state, he usually spared them." },
  { zh: "由是文武樂為之用。", literal: "Therefore civil and military men were glad to serve him.", idiomatic: "Civil and military men were glad to serve him." },
  { zh: "世子澄秘不發喪，唯行台左丞陳元康知之。", literal: "Heir Cheng kept the death secret and did not announce mourning; only Secretariat Left Assistant Director Chen Yuankang knew.", idiomatic: "Heir Gao Cheng kept the death secret; only Grand Secretariat left assistant director Chen Yuankang knew." },
  { zh: "侯景自念已與高氏有隙，內不自安。", literal: "Hou Jing reflected that he already had a rift with the Gao house and was inwardly ill at ease.", idiomatic: "Hou Jing knew he was at odds with the Gao house and could not rest easy." },
  { zh: "辛亥，據河南叛，歸於魏，穎州刺史司馬世雲以城應之。", literal: "On xinhai, he seized Henan and rebelled, going over to Wei; Yingzhou Inspector Sima Shiyun surrendered the city to him.", idiomatic: "On xinhai he seized Henan and rebelled, defecting to Western Wei; Yingzhou inspector Sima Shiyun surrendered his city." },
  { zh: "景誘執豫州刺史高元成、襄州刺史李密、廣州刺史懷朔暴顯等。", literal: "Jing lured and seized Yuzhou Inspector Gao Yuancheng, Xiangzhou Inspector Li Mi, Guangzhou Inspector of Huaishuo Bao Xian, and others.", idiomatic: "Jing lured and seized Yuzhou inspector Gao Yuancheng, Xiangzhou inspector Li Mi, Guangzhou inspector Bao Xian of Huaishuo, and others." },
  { zh: "遣軍士二百人載仗，暮入西兗州，欲襲取之。", literal: "He sent two hundred soldiers carrying arms; at dusk they entered Western Yanzhou intending a surprise seizure.", idiomatic: "He sent two hundred armed men into Western Yanzhou at dusk to seize it by surprise." },
  { zh: "刺史邢子才覺之，掩捕，盡獲之。", literal: "Inspector Xing Zicai detected them, struck and seized them, and took them all.", idiomatic: "Inspector Xing Zicai detected them, struck, and took them all." },
  { zh: "因散檄東方諸州，各為之備，由是景不能取。", literal: "He then scattered proclamations to the eastern provinces, each to prepare; thus Jing could not take them.", idiomatic: "He then sent proclamations to the eastern provinces to prepare; Jing could take nothing." },
  { zh: "諸將皆以為景之叛由崔暹，澄不得已，欲殺暹以謝景。", literal: "The generals all held that Jing's rebellion was because of Cui Xuan; Cheng had no choice and wished to kill Xuan to appease Jing.", idiomatic: "The generals blamed Jing's rebellion on Cui Xuan; Gao Cheng, cornered, meant to kill Xuan to appease Jing." },
  { zh: "陳元康諫曰：「今雖四海未清，綱紀已定；", literal: "Chen Yuankang remonstrated: \"Though the four seas are not yet clear, the laws and standards are already set;", idiomatic: "Chen Yuankang remonstrated: \"Though the realm is not yet pacified, law and order stand;" },
  { zh: "若以數將在外，苟悅其心，枉殺無辜，虧廢刑典，豈直上負天神，何以下安黎庶！", literal: "if because several generals are abroad you would please his heart and wrongly kill the innocent, damaging and abandoning the penal code—would you not above betray Heaven and spirits, and below how comfort the people!", idiomatic: "if you kill the innocent to please a rebel general abroad, you betray Heaven above and the people below!" },
  { zh: "晁錯前事，願公慎之。", literal: "The precedent of Chao Cuo—may my lord be careful.", idiomatic: "Remember Chao Cuo—be careful, my lord." },
  { zh: "」澄乃止，遣司空韓軌督諸軍討景。", literal: "\" Cheng then stopped and sent Minister of Works Han Gui to command the armies against Jing.", idiomatic: "\" Gao Cheng desisted and sent Minister of Works Han Gui to command the armies against Jing." },
  { zh: "辛酉，上祀南郊，大赦；", literal: "On xinyou, the emperor sacrificed at the southern suburb and proclaimed a general amnesty;", idiomatic: "On xinyou the Liang emperor sacrificed at the southern suburb and proclaimed a general amnesty;" },
  { zh: "甲子，祀明堂。", literal: "on jiazi, sacrificed at the Bright Hall.", idiomatic: "on jiazi he sacrificed at the Bright Hall." },
  { zh: "二月，魏詔：「自今應宮刑者，直沒官，勿刑。", literal: "In the second month, Western Wei decreed: \"From now on those who should suffer palace punishment shall be directly assigned to government service—do not mutilate.", idiomatic: "In the second month Western Wei decreed: \"From now on those liable to palace punishment shall be assigned to government service—no mutilation.\"" },
  { zh: "魏以開府儀同三司若於惠為司空，侯景為太傅、河南大行台、上谷公。", literal: "Western Wei made Acting Three Excellencies Ruo Yu Hui Minister of Works, and Hou Jing Grand Tutor, Grand Secretariat of Henan, and Duke of Shanggu.", idiomatic: "Western Wei made Ruo Yu Hui Minister of Works and Hou Jing Grand Tutor, Grand Secretariat of Henan, and Duke of Shanggu." },
  { zh: "庚辰，景又遣其行台郎中丁和來，上表言：「臣與高澄有隙，請舉函谷以東，瑕丘以西，豫、廣、穎、荊、襄、兗、南兗、濟、東豫、洛、陽、北荊、北揚等十三州內附，惟青、徐數州，僅須折簡。", literal: "On gengchen, Jing again sent his Grand Secretariat Lang Ding He, who memorialized: \"Your servant has a rift with Gao Cheng and asks to offer east of Hangu Pass and west of Xiaqiu—Yu, Guang, Ying, Jing, Xiang, Yan, Southern Yan, Ji, Eastern Yu, Luo, Yang, Northern Jing, Northern Yang, thirteen provinces in submission; only Qing and Xu need but a folded letter.", idiomatic: "On gengchen Jing sent his Grand Secretariat lang Ding He with a memorial: \"I am at odds with Gao Cheng and offer east of Hangu Pass and west of Xiaqiu—thirteen provinces: Yu, Guang, Ying, Jing, Xiang, Yan, Southern Yan, Ji, Eastern Yu, Luo, Yang, Northern Jing, and Northern Yang. Qing and Xu need only a folded letter.\"" },
  { zh: "且黃河以南，皆臣所職，易同反掌。", literal: "Moreover south of the Yellow River is all territory under my charge—as easy as turning the palm.", idiomatic: "South of the Yellow River is all mine—as easy as turning my palm." },
  { zh: "若齊、宋一平，徐事燕、趙。", literal: "If Qi and Song are pacified in time, Yan and Zhao will follow in due course.", idiomatic: "Pacify Qi and Song in time, and Yan and Zhao will follow." },
  { zh: "」上召群臣廷議。", literal: "\" The emperor summoned the ministers for court deliberation.", idiomatic: "\" The emperor summoned the ministers to debate." },
  { zh: "尚書僕射謝舉等皆曰：「頃歲與魏通和，邊境無事，今納其叛臣，竊謂非宜。", literal: "Vice Minister of the Masters of Writing Xie Ju and others all said: \"In recent years we have been at peace with Wei and the borders have been quiet; now to accept their rebel minister—I privately think it unfitting.", idiomatic: "Vice minister Xie Ju and others said: \"We have been at peace with Wei and the borders quiet; to accept their rebel—I think it unwise.\"" },
  { zh: "」上曰：「雖然，得景則塞北可清；", literal: "\" The emperor said: \"Even so, with Jing gained the north of the passes can be cleared;", idiomatic: "\" The emperor said: \"Even so, with Jing the north can be cleared;\"" },
  { zh: "機會難得，豈宜膠柱！", literal: "the opportunity is hard to win—how can we stick to the peg!", idiomatic: "the chance is rare—how can we stick to precedent!\"" },
  { zh: "是歲，正月，乙卯，上夢中原牧守皆以地來降，舉朝稱慶。", literal: "That year, in the first month, on yimao, the emperor dreamed that governors and prefects of the central plains all came offering their territories in surrender; the whole court celebrated.", idiomatic: "That year, in the first month, on yimao, the emperor dreamed that every governor and prefect of the central plains offered his territory; the court rejoiced." },
  { zh: "旦，見中書舍人朱異，告之，旦曰：「吾為人少夢，若有夢，必實。", literal: "At dawn he saw Secretariat Attendant Zhu Yi and told him; Yi said: \"I dream little; if I dream, it is sure to be real.", idiomatic: "At dawn he told Secretariat Attendant Zhu Yi, who said: \"I dream little; when I dream, it comes true.\"" },
  { zh: "」異曰：「此乃宇內混壹之兆也。", literal: "\" Yi said: \"This is an omen that the realm within the four seas will be united.", idiomatic: "\" Yi said: \"This is an omen that the realm will be united.\"" },
  { zh: "」及丁和至，稱景定計以正月乙卯，上愈神之。", literal: "\" When Ding He arrived and said Jing had fixed the plan on yimao of the first month, the emperor was all the more awed.", idiomatic: "\" When Ding He arrived and said Jing had fixed the plan on yimao of the first month, the emperor was all the more convinced it was fate." },
  { zh: "然意猶未決，嘗獨言：「我國家如金甌，無一傷缺，今忽受景地，詎是事宜？", literal: "Yet his mind was still undecided; he once said alone: \"Our state is like a golden bowl without a chip; now suddenly to accept Jing's territory—is this fitting?", idiomatic: "Yet he still hesitated and once said alone: \"Our state is a golden bowl without a chip; to accept Jing's land suddenly—is that wise?\"" },
  { zh: "脫致紛紜，悔之何及？", literal: "If it brings turmoil, how will regret avail?", idiomatic: "If it brings chaos, regret will come too late." },
  { zh: "」朱異揣知上意，對曰：「聖明御宇，南北歸仰，正以事無機會，未達其心。", literal: "\" Zhu Yi guessed the emperor's mind and replied: \"Your sage brilliance rules the realm; north and south look up to you—only because there has been no opportunity have they not reached their hearts.", idiomatic: "\" Zhu Yi read his mind and said: \"Your sage rule draws north and south—only for lack of opportunity have they not come forward.\"" },
  { zh: "今侯景分魏土之半以來，自非天誘其衷，人讚其謀，何以至此！", literal: "Now Hou Jing comes offering half of Wei's soil—if not Heaven guiding his inmost heart and men praising his plan, how could it reach this!", idiomatic: "Now Hou Jing brings half of Wei's territory—unless Heaven guides him and men praise his plan, how could this be!\"" },
  { zh: "若拒而不內，恐絕後來之望。", literal: "If you refuse and do not admit him, I fear you will cut off hope for those who come after.", idiomatic: "Refuse him and you cut off those who would follow." },
  { zh: "此誠易見，願陛下無疑。", literal: "This is truly easy to see—may Your Majesty have no doubt.", idiomatic: "This is plain—have no doubt, Your Majesty." },
  { zh: "」上乃定議納景。", literal: "\" The emperor then fixed the decision to accept Jing.", idiomatic: "\" The emperor decided to accept Jing." },
  { zh: "壬午，以景為大將軍，封河南王，都督河南北諸軍事、大行台，承製如鄧禹故事。", literal: "On renwu, Jing was made Grand General, enfeoffed as King of Henan, Commander-in-Chief of military affairs north and south of the river and Grand Secretariat, with authority to issue edicts as in Deng Yu's precedent.", idiomatic: "On renwu Jing was made Grand General and King of Henan, commander north and south of the river and Grand Secretariat, with edict authority as Deng Yu had held." },
  { zh: "平西咨議參軍周弘正，善占候，前此謂人曰：「國家數年後當有兵起。", literal: "Pingxi Advisory Staff Officer Zhou Hongzheng was skilled at divination; earlier he had told people: \"The state will have war rise in several years.", idiomatic: "Zhou Hongzheng, Pingxi advisory staff officer, was skilled at divination and had told people: \"War will come to the state in a few years.\"" },
  { zh: "」及聞納景，曰：「亂階在此矣！", literal: "\" When he heard Jing was accepted, he said: \"The stairway to chaos is here!", idiomatic: "\" When he heard Jing was accepted, he said: \"Here is the stairway to chaos!\"" },
  { zh: "丁亥，上耕藉田。", literal: "On dinghai, the emperor plowed the sacred field.", idiomatic: "On dinghai the emperor plowed the sacred field." },
  { zh: "三月，庚子，上幸同泰寺，捨身如大通故事。", literal: "In the third month, on gengzi, the emperor visited Tongtai Temple and surrendered his person as in the Datong precedent.", idiomatic: "In the third month, on gengzi, the emperor went to Tongtai Temple and surrendered his person as in the Datong precedent." },
  { zh: "甲辰，遣司州刺史羊鴉仁督兗州刺史桓和、仁州刺史湛海珍等，將兵三萬趣懸瓠，運糧食應接侯景。", literal: "On jiachen, he sent Sizhou Inspector Yang Yaren to command Yanzhou Inspector Huan He, Renzhou Inspector Zhan Haizhen, and others with thirty thousand troops toward Xuanhuo, transporting grain to support Hou Jing.", idiomatic: "On jiachen he sent Sizhou inspector Yang Yaren with Yanzhou inspector Huan He, Renzhou inspector Zhan Haizhen, and thirty thousand men toward Xuanhuo with grain for Hou Jing." },
  { zh: "魏大赦。", literal: "Western Wei proclaimed a general amnesty.", idiomatic: "Western Wei proclaimed a general amnesty." },
  { zh: "東魏高澄慮諸州有變，乃自出巡撫。", literal: "Eastern Wei's Gao Cheng feared changes in the provinces and went out himself to tour and reassure them.", idiomatic: "Gao Cheng of Eastern Wei feared trouble in the provinces and toured them himself." },
  { zh: "留段韶守晉陽，委以軍事；", literal: "He left Duan Shao to guard Jinyang and entrusted him with military affairs;", idiomatic: "He left Duan Shao at Jinyang with military command;" },
  { zh: "以丞相功曹趙彥深為大行台都官郎中。", literal: "he made Chancellor's Merit Officer Zhao Yanshen Grand Secretariat Director of Officials.", idiomatic: "and made chancellor's merit officer Zhao Yanshen Grand Secretariat director of officials." },
  { zh: "使陳元康豫作丞相歡條教數十紙付韶及彥深，在後以次行之。", literal: "He had Chen Yuankang prepare in advance several dozen sheets of Chancellor Huan's regulations and give them to Shao and Yanshen, to be carried out in order afterward.", idiomatic: "Chen Yuankang prepared dozens of sheets of Gao Huan's regulations for Shao and Yanshen to execute in order." },
  { zh: "臨發，握彥深手泣曰：「以母、弟相托，幸明此心！", literal: "At departure he grasped Yanshen's hand and wept: \"I entrust my mother and younger brother to you—pray make this heart clear!", idiomatic: "At departure he grasped Yanshen's hand and wept: \"I entrust my mother and brother to you—understand my heart!\"" },
  { zh: "」夏，四月，壬申，澄入朝於鄴。", literal: "\" In summer, the fourth month, on renshen, Cheng entered court at Ye.", idiomatic: "\" In summer, the fourth month, on renshen, Gao Cheng entered court at Ye." },
  { zh: "東魏主與之宴，澄起舞，識者知其不終。", literal: "The Eastern Wei ruler feasted with him; Cheng danced; those who understood knew he would not reach the end.", idiomatic: "The Eastern Wei emperor feasted with him; Cheng danced; those who knew saw he would not finish his course." },
  { zh: "丙子，群臣奉贖。", literal: "On bingzi, the ministers presented ransom.", idiomatic: "On bingzi the ministers presented ransom." },
  { zh: "丁亥，上還宮，大赦，改元，如大通故事。", literal: "On dinghai, the emperor returned to the palace, proclaimed a general amnesty, and changed the era name, as in the Datong precedent.", idiomatic: "On dinghai the emperor returned to the palace, amnestied, and changed the era name as in the Datong precedent." },
  { zh: "甲午，東魏遣兼散騎常侍李系來聘。", literal: "On jiawu, Eastern Wei sent Acting Palace Attendant Li Xi on a friendly mission.", idiomatic: "On jiawu Eastern Wei sent Acting Palace Attendant Li Xi on a friendly mission." },
  { zh: "系，繪之弟也。", literal: "Xi was the younger brother of Hui.", idiomatic: "Xi was the younger brother of Li Hui." },
  { zh: "五月，丁酉朔，東魏大赦。", literal: "In the fifth month, on the first day dingyou, Eastern Wei proclaimed a general amnesty.", idiomatic: "In the fifth month, on new year's day dingyou, Eastern Wei proclaimed a general amnesty." },
  { zh: "戊戌，東魏以襄城王旭為太尉。", literal: "On wuxu, Eastern Wei made Prince of Xiangcheng Xu Grand Commandant.", idiomatic: "On wuxu Eastern Wei made Prince Xu of Xiangcheng Grand Commandant." },
  { zh: "高澄遣武衛將軍元柱等將數萬眾晝夜兼行以襲侯景，遇景於穎川北，柱等大敗。", literal: "Gao Cheng sent Martial Guard General Yuan Zhu and others with tens of thousands marching day and night together to strike Hou Jing; they met Jing north of Yingchuan; Zhu and the rest were greatly defeated.", idiomatic: "Gao Cheng sent Martial Guard General Yuan Zhu with tens of thousands marching day and night to strike Hou Jing; they met north of Yingchuan and were routed." },
  { zh: "景以羊鴉仁等軍猶未至，乃退保穎川。", literal: "Jing, because Yang Yaren's army had not yet arrived, then withdrew to hold Yingchuan.", idiomatic: "Jing, since Yang Yaren had not yet arrived, withdrew to hold Yingchuan." },
  { zh: "甲辰，東魏以開府儀同三司庫狄干為太師，錄尚書事孫騰為太傅，汾州刺史賀拔仁為太保，司徒高隆之錄尚書事，司空韓軌為司徒，青州刺史尉景為大司馬，領軍將軍可朱渾道元為司空，僕射高洋為尚書令、領中書監，徐州刺史慕容紹宗為尚書左僕射，高陽王斌為右僕射。", literal: "On jiachen, Eastern Wei made Acting Three Excellencies Kudi Gan Grand Preceptor, Director of the Masters of Writing Sun Teng Grand Tutor, Fenzhou Inspector Heba Ren Grand Guardian, Minister over the Masses Gao Longzhi Director of the Masters of Writing, Minister of Works Han Gui Minister over the Masses, Qingzhou Inspector Wei Jing Grand Marshal, Palace Guard General Kezhunhun Daoyuan Minister of Works, Vice Minister Gao Yang Minister of the Masters of Writing and concurrent Director of the Secretariat, Xuzhou Inspector Murong Shaozong Left Vice Minister of the Masters of Writing, and Prince of Gaoyang Bin Right Vice Minister.", idiomatic: "On jiachen Eastern Wei appointed Kudi Gan Grand Preceptor, Sun Teng Grand Tutor and director of the Masters of Writing, Heba Ren Grand Guardian, Gao Longzhi director of the Masters of Writing, Han Gui Minister over the Masses, Wei Jing Grand Marshal, Kezhunhun Daoyuan Minister of Works, Gao Yang Minister of the Masters of Writing and director of the Secretariat, Murong Shaozong left vice minister, and Prince Bin of Gaoyang right vice minister." },
  { zh: "戊午，尉景卒。", literal: "On wuwu, Wei Jing died.", idiomatic: "On wuwu Wei Jing died." },
  { zh: "韓軌等圍侯景於穎川。", literal: "Han Gui and others besieged Hou Jing at Yingchuan.", idiomatic: "Han Gui besieged Hou Jing at Yingchuan." },
  { zh: "景懼，割東荊、北兗州、魯陽、長社四城賂魏以求救。", literal: "Jing was afraid and ceded Eastern Jing, Northern Yanzhou, Luyang, and Changshe—four cities—to bribe Wei and seek rescue.", idiomatic: "Jing, afraid, ceded Eastern Jing, Northern Yanzhou, Luyang, and Changshe to Western Wei for rescue." },
  { zh: "尚書左僕射於謹曰：「景少習兵，奸詐難測，不如厚其爵位以觀其變，未可遣兵也。", literal: "Left Vice Minister of the Masters of Writing Yu Jin said: \"Jing has studied war from youth; treacherous and hard to fathom—better enrich his rank and title and watch his changes; do not yet send troops.", idiomatic: "Left vice minister Yu Jin said: \"Jing knows war and is treacherous—enrich his rank and watch him; do not send troops yet.\"" },
  { zh: "」荊州刺史王思政以為：「若不因機進取，後悔無及。", literal: "\" Jingzhou Inspector Wang Sizheng held: \"If we do not seize the moment and advance, regret will come too late.", idiomatic: "\" Jingzhou inspector Wang Sizheng said: \"Miss this chance and regret will come too late.\"" },
  { zh: "」即以荊州步騎萬餘從魯陽關向陽翟。", literal: "\" He immediately led more than ten thousand Jingzhou foot and horse from Luyang Pass toward Yangdi.", idiomatic: "\" He led more than ten thousand Jingzhou foot and horse from Luyang Pass toward Yangdi." },
  { zh: "丞相泰聞之，加景大將軍兼尚書令，遣太尉李弼、儀同三司趙貴將兵一萬赴穎川。", literal: "Chancellor Tai heard and promoted Jing to Grand General and concurrent Minister of the Masters of Writing, and sent Grand Commandant Li Bi and Acting Three Excellencies Zhao Gui with ten thousand troops to Yingchuan.", idiomatic: "Yuwen Tai heard and made Jing Grand General and concurrent minister of the Masters of Writing, and sent Li Bi and Zhao Gui with ten thousand men to Yingchuan." },
  { zh: "景恐上責之，遣中兵參軍柳□開奉啟於上，以為：「王旅未接，死亡交急，遂求援關中，自救目前。", literal: "Jing feared the emperor would blame him and sent Central Army Staff Officer Liu □ Kai with a memorial to the emperor, stating: \"The royal army has not yet joined; death presses close—I therefore sought aid in Guanzhong to save myself for the moment.", idiomatic: "Jing feared blame from the Liang emperor and sent central army staff officer Liu □ Kai with a memorial: \"The imperial army has not joined; death presses close—I sought Guanzhong aid to save myself for the moment.\"" },
  { zh: "臣既不安於高氏，豈見容於宇文！", literal: "Your servant is already ill at ease with the Gao house—how could he be tolerated by the Yuwen!", idiomatic: "I am ill at ease with the Gao—how could the Yuwen tolerate me!\"" },
  { zh: "但螫手解腕，事不得已，本圖為國，願不賜咎！", literal: "But when the hand is stung one cuts off the wrist—the matter could not be helped; the original plan was for the state—may you not bestow blame!", idiomatic: "But when the hand is stung one cuts the wrist—the matter could not be helped; I meant it for the state—do not blame me!\"" },
  { zh: "臣獲其力，不容即棄，今以四州之地為餌敵之資，已令宇文遣人入守。", literal: "Your servant gained their strength and cannot cast it off at once; now I use four provinces as bait for the enemy and have already ordered the Yuwen to send men to garrison them.", idiomatic: "I gained their strength and cannot cast it off; I used four provinces as bait and have already let the Yuwen garrison them." },
  { zh: "自豫州以東，齊海以西，悉臣控壓；", literal: "From Yuzhou east and the Qi sea west—all is under your servant's control;", idiomatic: "From Yuzhou east to the Qi sea west—all is mine;" },
  { zh: "見有之地，盡歸聖朝，懸瓠、項城、徐州、南兗，事須迎納。", literal: "all territory now held returns entirely to the sacred court; Xuanhuo, Xiangcheng, Xuzhou, and Southern Yan must be received and admitted.", idiomatic: "all I hold returns to Your Majesty; Xuanhuo, Xiangcheng, Xuzhou, and Southern Yan must be received." },
  { zh: "願陛下速敕境上，各置重兵，與臣影響，不使差互！", literal: "May Your Majesty quickly order the borders, each place heavy troops, moving in shadow and echo with your servant—let there be no mismatch!", idiomatic: "Order the borders garrisoned at once, heavy troops in step with me—let nothing fall out of line!\"" },
  { zh: "」上報之曰：「大夫出境，尚有所專；", literal: "\" The emperor replied: \"A grandee leaving the borders still has some discretion;", idiomatic: "\" The emperor replied: \"A minister abroad still has discretion;\"" },
  { zh: "況始創奇謀，將建大業，理須適事而行，隨方以應。", literal: "how much more when first launching a strange plan and about to build a great enterprise—reason demands acting as the matter requires and responding as the place demands.", idiomatic: "how much more when launching a great design—you must act as the moment requires and answer each place in turn." },
  { zh: "卿誠心有本，何假詞費！", literal: "Your sincere heart has its root—why borrow wasted words!", idiomatic: "Your heart is true—why waste words!\"" },
  { zh: "魏以開府儀同三司獨孤信為大司馬。", literal: "Western Wei made Acting Three Excellencies Dugu Xin Grand Marshal.", idiomatic: "Western Wei made Dugu Xin Grand Marshal." },
  { zh: "六月，戊辰，以鄱陽王范為征北將軍，總督漢北征討諸軍事，擊穰城。", literal: "In the sixth month, on wuchen, Prince of Poyang Fan was made Suppressing-the-North General, overall commander of military affairs for campaigns north of the Han, and attacked Rangcheng.", idiomatic: "In the sixth month, on wuchen, Prince Fan of Poyang was made Suppressing-the-North General, overall commander north of the Han, and attacked Rangcheng." },
  { zh: "東魏韓軌等圍穎川，聞魏李弼、趙貴等將至，己巳，引兵還鄴。", literal: "Eastern Wei's Han Gui and others besieged Yingchuan; hearing that Western Wei's Li Bi, Zhao Gui, and others were coming, on jisi they led the army back to Ye.", idiomatic: "Han Gui of Eastern Wei besieged Yingchuan; hearing Li Bi and Zhao Gui of Western Wei were coming, on jisi he withdrew to Ye." },
  { zh: "侯景欲因會執弼與貴，奪其軍；", literal: "Hou Jing wished to use a meeting to seize Bi and Gui and take their army;", idiomatic: "Hou Jing meant to seize Bi and Gui at a meeting and take their army;" },
  { zh: "貴疑之，不往。", literal: "Gui suspected this and did not go.", idiomatic: "Gui suspected it and stayed away." },
  { zh: "貴欲誘景入營而執之，弼止之。", literal: "Gui wished to lure Jing into camp and seize him; Bi stopped him.", idiomatic: "Gui wanted to lure Jing into camp and seize him; Bi stopped him." },
  { zh: "羊鴉仁遣長史鄧鴻將兵至汝水，弼引兵還長安。", literal: "Yang Yaren sent Chief of Staff Deng Hong with troops to the Ru River; Bi led the army back to Chang'an.", idiomatic: "Yang Yaren sent chief of staff Deng Hong to the Ru; Bi led his army back to Chang'an." },
  { zh: "王思政入據穎川。", literal: "Wang Sizheng entered and held Yingchuan.", idiomatic: "Wang Sizheng entered and held Yingchuan." },
  { zh: "景陽稱略地，引軍出屯懸瓠。", literal: "Jing openly claimed to be seizing territory and led the army out to camp at Xuanhuo.", idiomatic: "Jing openly claimed to be seizing territory and marched out to camp at Xuanhuo." },
  { zh: "景復乞兵於魏，丞相泰使同軌防主韋法保及都督賀蘭願德等將兵助之。", literal: "Jing again begged troops from Wei; Chancellor Tai sent Tonggui Defense Commander Wei Fabao and Commissioner Helan Yuande and others with troops to help him.", idiomatic: "Jing again begged troops from Western Wei; Yuwen Tai sent Tonggui defense commander Wei Fabao and commissioner Helan Yuande to help him." },
  { zh: "大行台左丞藍田王悅言於泰曰：「侯景之於高歡，始敦鄉黨之情，終定君臣之契，任居上將，位重台司；", literal: "Grand Secretariat Left Assistant Director Prince of Lantian Yue said to Tai: \"Hou Jing toward Gao Huan at first cultivated hometown feeling, in the end fixed the lord-and-minister bond; his post was supreme general, his rank weighed as Secretariat head;", idiomatic: "Grand Secretariat left assistant director Prince Yue of Lantian said to Yuwen Tai: \"Hou Jing and Gao Huan began as townsmen and ended as lord and minister; he was supreme general and head of the secretariat;" },
  { zh: "今歡始死，景遽外叛，蓋所圖甚大，終不為人下故也。", literal: "now Huan has just died and Jing suddenly rebels outward—surely his designs are very great; in the end he will not serve under another.", idiomatic: "now Gao Huan is barely dead and Jing rebels at once—his designs are large; he will never serve under another." },
  { zh: "且彼能背德於高氏，豈肯盡節於朝廷！", literal: "Moreover, if he can betray the Gao house, how would he be willing to die for the court!", idiomatic: "If he can betray the Gao, how will he die for our court!\"" },
  { zh: "今益之以勢，援之以兵，竊恐朝廷貽笑將來也。", literal: "Now to add power and aid him with troops—I privately fear the court will be laughed at in times to come.", idiomatic: "Give him power and troops and the court will be laughed at for ages." },
  { zh: "」泰乃召景入朝。", literal: "\" Tai then summoned Jing to court.", idiomatic: "\" Yuwen Tai then summoned Jing to court." },
  { zh: "景陰謀叛魏，事計未成，厚撫韋法保等，冀為己用，外示親密無猜間，每往來諸軍間，侍從至少，魏軍中名將，皆身自造詣。", literal: "Jing secretly plotted to rebel against Wei; the plan was not yet complete; he treated Wei Fabao and others generously, hoping to use them; outwardly he showed intimacy without suspicion; whenever he went among the armies his attendants were few; famous generals of Wei's armies he personally visited.", idiomatic: "Jing secretly plotted to rebel against Western Wei; the plan was not ripe; he treated Wei Fabao generously, hoping to win him, and showed open intimacy; he moved among the armies with few attendants and visited every famous Wei general in person." },
  { zh: "同軌防長史裴寬謂法保曰：「侯景狡詐，必不肯入關，欲托款於公，恐未可信。", literal: "Tonggui Defense Chief of Staff Pei Kuan said to Fabao: \"Hou Jing is crafty; he will surely not enter the passes and wishes to pledge goodwill to you—I fear he is not yet to be trusted.", idiomatic: "Tonggui defense chief of staff Pei Kuan told Fabao: \"Hou Jing is crafty; he will not enter the passes and means to win you—I fear him.\"" },
  { zh: "若伏兵斬之，此亦一時之功也。", literal: "If you set ambush and behead him, this too would be a moment's merit.", idiomatic: "Ambush and behead him—that would be a moment's merit." },
  { zh: "如其不爾，即應深為之防，不得信其誑誘，自貽後悔。", literal: "If not, you should deeply guard against him; you must not trust his deceit and enticement and bring regret on yourself.", idiomatic: "If not, guard deeply; do not trust his bait or regret will follow." },
  { zh: "」法保深然之，不敢圖景，但自為備而已；", literal: "\" Fabao deeply agreed but did not dare plot against Jing—only prepared for himself;", idiomatic: "\" Fabao agreed but did not dare move against Jing—only prepared himself;" },
  { zh: "尋辭還所鎮。", literal: "soon he took leave and returned to his command.", idiomatic: "soon he returned to his post." },
  { zh: "王思政亦覺其詐，密召賀蘭願德等還，分佈諸軍，據景七州、十二鎮。", literal: "Wang Sizheng also perceived his deceit, secretly recalled Helan Yuande and others, distributed the armies, and seized Jing's seven provinces and twelve garrisons.", idiomatic: "Wang Sizheng also saw through him, secretly recalled Helan Yuande, deployed the armies, and took Jing's seven provinces and twelve garrisons." },
  { zh: "景果辭不入朝，遺丞相泰書曰：「吾恥與高澄雁行，安能比肩大弟！", literal: "Jing indeed declined to enter court and sent Chancellor Tai a letter: \"I am ashamed to walk in file with Gao Cheng—how could I stand shoulder to shoulder with the great younger brother!", idiomatic: "Jing refused court and wrote Yuwen Tai: \"I am ashamed to walk in file with Gao Cheng—how could I stand shoulder to shoulder with his younger brother!\"" },
  { zh: "」泰乃遣行台郎中趙士憲悉召前後所遣諸軍援景者。", literal: "\" Tai then sent Grand Secretariat Lang Zhao Shixian to recall all armies sent before and after to aid Jing.", idiomatic: "\" Yuwen Tai sent Grand Secretariat lang Zhao Shixian to recall every army sent to aid Jing." },
  { zh: "景遂決意來降。", literal: "Jing then resolved to come over in surrender.", idiomatic: "Jing then resolved to surrender to Liang." },
  { zh: "魏將任約以所部千餘人降於景。", literal: "Wei general Ren Yue with more than a thousand of his command surrendered to Jing.", idiomatic: "Wei general Ren Yue surrendered more than a thousand men to Jing." },
  { zh: "泰以所授景使持節、太傅、大將軍、兼尚書令、河南大行台、都督河南諸軍事回授王思政，思政並讓不受；", literal: "Tai transferred to Wang Sizheng all titles he had given Jing—Bearer of the Staff, Grand Tutor, Grand General, concurrent Minister of the Masters of Writing, Grand Secretariat of Henan, Commander of military affairs in Henan; Sizheng declined them all and would not accept;", idiomatic: "Yuwen Tai transferred to Wang Sizheng every title he had given Jing; Sizheng declined all;" },
  { zh: "頻使敦諭，唯受都督河南諸軍事。", literal: "messengers were repeatedly sent to urge him; he accepted only Commander of military affairs in Henan.", idiomatic: "messengers urged him repeatedly; he accepted only command of military affairs in Henan." },
  { zh: "高澄將如晉陽，以弟洋為京畿大都督，留守於鄴，使黃門侍郎高德政佐之。", literal: "Gao Cheng was about to go to Jinyang; he made his younger brother Yang Metropolitan Commander of the Capital Region, left him at Ye, and had Yellow Gate Attendant Gao Dezheng assist him.", idiomatic: "Gao Cheng was going to Jinyang; he left his brother Gao Yang as metropolitan commander at Ye with Yellow Gate Attendant Gao Dezheng to assist." },
  { zh: "德政，顥之子也。", literal: "Dezheng was the son of Hao.", idiomatic: "Dezheng was the son of Gao Hao." },
  { zh: "丁丑，澄還晉陽，始發喪。", literal: "On dingchou, Cheng returned to Jinyang and first announced mourning.", idiomatic: "On dingchou Gao Cheng returned to Jinyang and announced mourning." },
  { zh: "秋，七月，魏長樂武烈公若於惠卒。", literal: "In autumn, the seventh month, Western Wei Duke of Changle, Martial and Fierce, Ruo Yu Hui, died.", idiomatic: "In autumn, the seventh month, Ruo Yu Hui, Western Wei's Duke of Changle, died." },
  { zh: "丁酉，東魏主為丞相歡舉哀，服緦縗，凶禮依漢霍光故事，贈相國、齊王，備九錫殊禮。", literal: "On dingyou, the Eastern Wei ruler mourned Chancellor Huan, wearing hemp and coarse sackcloth; funeral rites followed Han Huo Guang's precedent; posthumous gifts were Chancellor of State and King of Qi, with the full nine bestowals of special honor.", idiomatic: "On dingyou the Eastern Wei emperor mourned Gao Huan in hemp, following Huo Guang's precedent, posthumously making him chancellor of state and King of Qi with the full nine bestowals." },
  { zh: "戊戌，以高澄為使持節、大丞相、都督中外諸軍、錄尚書事、大行台、勃海王；", literal: "On wuxu, Gao Cheng was made Bearer of the Staff, Grand Chancellor, Commander of all armies within and without, Director of the Masters of Writing, Grand Secretariat, and Prince of Bohai;", idiomatic: "On wuxu Gao Cheng was made Bearer of the Staff, grand chancellor, commander of all armies, director of the Masters of Writing, Grand Secretariat, and Prince of Bohai;" },
  { zh: "澄啟辭爵位。", literal: "Cheng memorialized declining the noble rank.", idiomatic: "Gao Cheng declined the noble rank." },
  { zh: "壬寅，詔太原公洋攝理軍國，遣中使敦諭澄。", literal: "On renyin, an edict ordered Duke of Taiyuan Yang to administer state and army; palace envoys were sent to urge Cheng.", idiomatic: "On renyin an edict ordered Duke Gao Yang of Taiyuan to administer state and army and sent envoys to urge Gao Cheng." },
  { zh: "庚申，羊鴉仁入懸瓠城。", literal: "On gengshen, Yang Yaren entered Xuanhuo city.", idiomatic: "On gengshen Yang Yaren entered Xuanhuo." },
  { zh: "甲子，詔更以懸瓠為豫州，壽春為南豫州，改合肥為合州。", literal: "On jiazi, an edict changed Xuanhuo back to Yuzhou, Shouchun to Southern Yuzhou, and Hefei to Hezhou.", idiomatic: "On jiazi an edict made Xuanhuo Yuzhou again, Shouchun Southern Yuzhou, and Hefei Hezhou." },
  { zh: "以鴉仁為司、豫二州刺史，鎮縣瓠；", literal: "Yaren was made Inspector of Si and Yu and garrisoned Xuanhuo;", idiomatic: "Yaren was made inspector of Si and Yu and garrisoned Xuanhuo;" },
  { zh: "西陽太守羊思達為殷州刺史，鎮項城。", literal: "Xiyang Administrator Yang Sida was made Yinzhou Inspector and garrisoned Xiangcheng.", idiomatic: "Xiyang administrator Yang Sida was made Yinzhou inspector at Xiangcheng." },
  { zh: "八月，乙丑，下詔大舉伐東魏。", literal: "In the eighth month, on yichou, an edict was issued for a great campaign against Eastern Wei.", idiomatic: "In the eighth month, on yichou, an edict launched a great campaign against Eastern Wei." },
  { zh: "遣南豫州刺史貞陽侯淵明、南兗州刺史南康王會理分督諸將。", literal: "Nanzhou Inspector Marquis of Zhenyang Yuanming and Southern Yanzhou Inspector Prince of Nankang Huili were sent to divide command of the generals.", idiomatic: "Nanzhou inspector Marquis Xiao Yuanming of Zhenyang and Southern Yanzhou inspector Prince Xiao Huili of Nankang were sent to command the generals." },
  { zh: "淵明，懿之子；", literal: "Yuanming was the son of Yi;", idiomatic: "Yuanming was the son of Xiao Yi;" },
  { zh: "會理，績之子也。", literal: "Huili was the son of Ji.", idiomatic: "Huili was the son of Xiao Ji." },
  { zh: "始，上欲以鄱陽王范為元帥；", literal: "At first the emperor wished to make Prince of Poyang Fan commander-in-chief;", idiomatic: "At first the emperor wanted Prince Fan of Poyang as commander-in-chief;" },
  { zh: "朱異取急在外，聞之，遽入曰：「鄱陽雄豪蓋世，得人死力，然所至殘暴，非弔民之材。", literal: "Zhu Yi was on urgent leave outside; hearing this, he hurried in and said: \"Poyang is a hero unmatched in his age and wins men's death-dealing strength, yet wherever he goes he is brutal—not material for comforting the people.", idiomatic: "Zhu Yi was on leave outside; hearing this, he hurried in and said: \"Poyang is a peerless hero who wins men's death-dealing loyalty, but wherever he goes he is brutal—not a man to comfort the people.\"" },
  { zh: "且陛下昔登北顧亭以望，謂江右有反氣，骨肉為戎首。", literal: "Moreover Your Majesty once climbed Beigu Pavilion to look and said the lands right of the river had a rebellious air—flesh and bone as war-leaders.", idiomatic: "Your Majesty once climbed Beigu Pavilion and said the lands south of the Yangzi had a rebellious air—kin as war-leaders." },
  { zh: "今日之事，尤宜詳擇。", literal: "Today's matter should be chosen with especial care.", idiomatic: "Today's choice needs especial care." },
  { zh: "」上默然，曰：「會理何如？", literal: "\" The emperor was silent and said: \"How about Huili?", idiomatic: "\" The emperor was silent. \"How about Huili?\"" },
  { zh: "」對曰：「陛下得之矣。", literal: "\" He replied: \"Your Majesty has found the man.", idiomatic: "\" He said: \"Your Majesty has found the man.\"" },
  { zh: "」會理懦而無謀，所乘襻輿，施板屋，冠以牛皮。", literal: "\" Huili was timid and without strategy; the palanquin he rode had a plank house built on it, topped with oxhide.", idiomatic: "\" Huili was timid and witless; his palanquin had a plank house roofed with oxhide." },
  { zh: "上聞，不悅。", literal: "The emperor heard and was displeased.", idiomatic: "The emperor heard and was displeased." },
  { zh: "貞陽侯淵明時鎮壽陽，屢請行，上許之。", literal: "Marquis of Zhenyang Yuanming was then garrisoning Shouchun; he repeatedly asked to go; the emperor permitted it.", idiomatic: "Marquis Yuanming of Zhenyang was at Shouchun and repeatedly asked to go; the emperor agreed." },
  { zh: "會理自以皇孫，復為都督，自淵明已下，殆不對接。", literal: "Huili, taking himself for an imperial grandson and again made commander, from Yuanming downward scarcely received audience.", idiomatic: "Huili, as imperial grandson and commander, scarcely deigned to receive Yuanming and those below." },
  { zh: "淵明與諸將密告朱異，追會理還，遂以淵明為都督。", literal: "Yuanming and the generals secretly reported to Zhu Yi; Huili was recalled and Yuanming was made commander.", idiomatic: "Yuanming and the generals secretly told Zhu Yi; Huili was recalled and Yuanming made commander." },
  { zh: "辛未，高澄入朝於鄴，固辭大丞相；", literal: "On xinwei, Gao Cheng entered court at Ye and firmly declined Grand Chancellor;", idiomatic: "On xinwei Gao Cheng entered court at Ye and firmly declined grand chancellor;" },
  { zh: "詔為大將軍如故，餘如前命。", literal: "an edict made him Grand General as before; the rest as in the previous order.", idiomatic: "an edict made him Grand General as before; the rest stood." },
  { zh: "甲申，虛葬齊獻武王於漳水之西；", literal: "On jiashen, a false burial of King Xianwu of Qi was performed west of the Zhang River;", idiomatic: "On jiashen a false burial of King Xianwu of Qi was performed west of the Zhang;" },
  { zh: "潛鑿成安鼓山石窟佛頂之旁為穴，納其柩而塞之，殺其群匠。", literal: "secretly a cave was cut beside the Buddha crown in the Chengan Gushan grotto, the coffin placed in and sealed, and the craftsmen killed.", idiomatic: "secretly they cut a cave beside the Buddha crown at Chengan Gushan, sealed the coffin inside, and killed the craftsmen." },
  { zh: "及齊之亡也，一匠之子知之，發石取金而逃。", literal: "When Qi perished, one craftsman's son knew; he opened the stone, took the gold, and fled.", idiomatic: "When Qi fell, a craftsman's son knew; he opened the stone, took the gold, and fled." },
  { zh: "戊子，武州刺史蕭弄璋攻東魏磧泉、呂梁二戍，拔之。", literal: "On wuzi, Wuzhou Inspector Xiao Nongzhang attacked Eastern Wei's Qiquan and Lüliang garrisons and took them.", idiomatic: "On wuzi Wuzhou inspector Xiao Nongzhang took Eastern Wei's Qiquan and Lüliang garrisons." },
  { zh: "或告東魏大將軍澄云：「侯景有北歸之志。", literal: "Someone reported to Eastern Wei Grand General Cheng: \"Hou Jing has a mind to return north.", idiomatic: "Someone told Gao Cheng: \"Hou Jing means to return north.\"" },
  { zh: "」會景將蔡道遵北歸，言「景頗知悔過」。", literal: "\" Just then Jing's general Cai Daozun returned north and said \"Jing knows his fault somewhat.\"", idiomatic: "\" Just then Jing's general Cai Daozun came north and said Jing knew his fault.\"" },
  { zh: "景母及妻子皆在鄴，澄乃以書諭之，語以闔門無恙，若還，許以豫州刺史終其身，還其寵妻、愛子，所部文武，更不追攝。", literal: "Jing's mother, wife, and children were all at Ye; Cheng then sent him a letter explaining that the whole household was unharmed; if he returned, he was promised Yuzhou Inspector for life, return of his favored wife and beloved son, and no further pursuit of his civil and military subordinates.", idiomatic: "Jing's mother, wife, and children were at Ye; Gao Cheng wrote that the household was safe—return and he could hold Yuzhou for life, with wife, son, and officers unmolested." },
  { zh: "景使王偉復書曰：「今已引二邦，揚旌北討，熊豹齊奮，克復中原，幸自取之，何勞恩賜！", literal: "Jing had Wang Wei reply: \"Now I have drawn two states, raised banners for northern campaign; bears and leopards strive together; to recover the central plains—pray take it yourselves; why trouble with gracious gifts!", idiomatic: "Jing had Wang Wei reply: \"I have drawn two states and march north; bears and leopards strive together to recover the central plains—take it yourselves; why trouble with gifts!\"" },
  { zh: "昔王陵附漢，母在不歸，太上囚楚，乞羹自若，矧伊妻子，而可介意！", literal: "In old times Wang Ling joined Han though his mother was alive and did not return; the Supreme Emperor was prisoner of Chu and begged for broth as if it were nothing—how much more wives and children—how could one mind them!", idiomatic: "Wang Ling joined Han though his mother lived; the Supreme Emperor was Chu’s prisoner and begged for broth unashamed—how much more wives and children!\"" },
  { zh: "脫謂誅之有益，欲止不能，殺之無損，徒復坑戮，家累在君，何關僕也！", literal: "If you say killing them would help and wish to stop but cannot, killing them would not harm me—you would only heap slaughter; the family's bonds are in your hands—what has that to do with your servant!", idiomatic: "If killing them would help you, you cannot stop yourself; if it would not harm me, you only heap slaughter—their fate is yours, not mine!\"" },
  { zh: "戊子，詔以景錄行台尚書事。", literal: "On wuzi, an edict made Jing Director of Grand Secretariat Masters of Writing affairs.", idiomatic: "On wuzi an edict made Jing director of Grand Secretariat affairs." },
  { zh: "東魏靜帝，美容儀，旅力過人，能挾石師子逾宮牆，射無不中；", literal: "Eastern Wei's Emperor Jing had handsome bearing; his strength surpassed other men; he could lift stone lions over the palace wall; in shooting nothing missed;", idiomatic: "Eastern Wei's Emperor Jing was handsome; his strength surpassed other men; he could lift stone lions over the palace wall and never missed a shot;" },
  { zh: "好文學，從容沉雅。", literal: "he loved literature and was easy and grave.", idiomatic: "he loved literature and was calm and grave." },
  { zh: "時人以為有孝文風烈，大將軍澄深忌之。", literal: "Men of the time thought he had Emperor Xiaowen's manner and spirit; Grand General Cheng deeply resented him.", idiomatic: "Men thought he had Emperor Xiaowen's spirit; Gao Cheng deeply resented him." },
  { zh: "始，獻武王自病逐君之丑，事靜帝禮甚恭，事無大小必以聞，可否聽旨。", literal: "At first King Xianwu, ashamed of the ugliness of deposing the ruler from his own illness, served Emperor Jing with great respect; matters large and small he always reported and awaited approval or refusal.", idiomatic: "At first Gao Huan, ashamed of deposing the emperor, served Emperor Jing with great respect and reported every matter for approval." },
  { zh: "每侍宴，俯伏上壽；", literal: "Whenever he attended feasts he bowed low and offered longevity;", idiomatic: "At every feast he bowed low and offered longevity;" },
  { zh: "帝設法會，乘輦行香，歡執香爐步從，鞠躬屏氣，承望顏色，故其下奉帝莫敢不恭。", literal: "when the emperor held a Buddhist assembly and rode the carriage scattering incense, Huan carried the censer and walked behind, bowing and holding his breath, watching his expression—therefore those below who served the emperor did not dare be disrespectful.", idiomatic: "when the emperor rode the carriage at a Buddhist assembly, Gao Huan carried the censer behind, bowing and holding his breath—so his subordinates dared not disrespect the emperor." },
  { zh: "及澄當國，倨慢頓甚，使中書黃門郎崔季舒察帝動靜，小大皆令季舒知之。", literal: "When Cheng held power, arrogance and contempt suddenly grew great; he had Secretariat Yellow Gate Lang Cui Jishu observe the emperor's movements; large and small all had to be known to Jishu.", idiomatic: "When Gao Cheng held power, arrogance grew; he had Cui Jishu watch the emperor's every move." },
  { zh: "澄與季舒書曰：「癡人比復何似？", literal: "Cheng wrote Jishu: \"How does the fool compare now?", idiomatic: "Gao Cheng wrote Jishu: \"How is the fool now?\"" },
  { zh: "癡勢小差未？", literal: "Has the fool's condition improved a little?", idiomatic: "Has his condition improved a little?\"" },
  { zh: "宜用心檢校。", literal: "You should use your heart to inspect and check.", idiomatic: "Watch him closely." },
  { zh: "」帝嘗獵於鄴東，馳逐如飛，監衛都督烏那羅受工伐從後呼曰：「天子勿走馬，大將軍嗔！", literal: "\" The emperor once hunted east of Ye, galloping in pursuit like flight; Supervising Guard Commissioner Wunaluo Shougongfa called from behind: \"Son of Heaven, do not gallop—the Grand General will be angry!", idiomatic: "\" The emperor once hunted east of Ye at a gallop; guard commissioner Wunaluo Shougongfa called from behind: \"Son of Heaven, do not gallop—the Grand General will be angry!\"" },
  { zh: "」澄嘗侍飲酒，舉大觴屬帝曰：「臣澄勸陛下酒。", literal: "\" Cheng once attended drinking, raised a great cup and urged the emperor: \"Your servant Cheng urges Your Majesty to drink.", idiomatic: "\" Gao Cheng once raised a great cup and urged the emperor: \"Your servant Cheng urges Your Majesty to drink.\"" },
  { zh: "」帝不勝忿，曰：「自古無不亡之國，朕亦何用此生為！", literal: "\" The emperor could not bear his anger and said: \"From antiquity there has been no state that did not perish—what use is this life to me!", idiomatic: "\" The emperor, furious, said: \"From antiquity no state failed to perish—what use is this life to me!\"" },
  { zh: "」澄怒曰：「朕，朕，狗腳朕！", literal: "\" Cheng raged: \"Imperial We, imperial We—dog-foot imperial We!", idiomatic: "\" Gao Cheng raged: \"Imperial We, imperial We—dog-foot imperial We!\"" },
  { zh: "」使崔季舒毆帝三拳，奮衣而出。", literal: "\" He had Cui Jishu beat the emperor three blows with the fist and flung his robes and went out.", idiomatic: "\" He had Cui Jishu strike the emperor three blows and stormed out." },
  { zh: "明日，澄使季舒入勞帝。", literal: "The next day Cheng sent Jishu in to console the emperor.", idiomatic: "The next day Gao Cheng sent Jishu to console the emperor." },
  { zh: "帝亦謝焉，賜季舒絹百匹。", literal: "The emperor also apologized and gave Jishu a hundred lengths of silk.", idiomatic: "The emperor also apologized and gave Jishu a hundred lengths of silk." },
  { zh: "帝不堪憂辱，詠謝靈運詩曰：「韓亡子房奮，秦帝魯連恥。", literal: "The emperor could not bear worry and insult and chanted Xie Lingyun's poem: \"When Han perished Zifang rose; the Qin emperor was shamed before Lu Lian.", idiomatic: "Unable to bear insult, the emperor chanted Xie Lingyun: \"When Han perished Zifang rose; the Qin emperor was shamed before Lu Lian.\"" },
  { zh: "本自江海人，忠義動君子。", literal: "Originally men of rivers and seas—loyalty and righteousness move gentlemen.", idiomatic: "Men of rivers and seas—loyalty and righteousness move gentlemen.\"" },
  { zh: "」常侍、侍講穎川荀濟知帝意，乃與祠部郎中元瑾、長秋卿劉思逸、華山王大器、淮南王宣洪、濟北王徽等謀誅澄。", literal: "\" Regular Attendant and Lecturer Yingchuan Xun Ji knew the emperor's mind and with Sacrificial Affairs Lang Yuan Jin, Director of the Long Autumn Liu Siyi, Prince of Huashan Daqi, Prince of Huainan Xuanhong, Prince of Jibei Hui, and others plotted to kill Cheng.", idiomatic: "\" Regular attendant and lecturer Xun Ji of Yingchuan read the emperor's mind and with Yuan Jin, Liu Siyi, Prince Daqi of Huashan, Prince Xuanhong of Huainan, Prince Hui of Jibei, and others plotted to kill Gao Cheng." },
  { zh: "大器，鷙之子也。", literal: "Daqi was the son of Zhi.", idiomatic: "Daqi was the son of Yuan Zhi." },
  { zh: "帝謬為敕問濟曰：「欲以何日開講？", literal: "The emperor falsely made an edict asking Ji: \"On what day do you wish to open the lecture?", idiomatic: "The emperor forged an edict asking Ji: \"On what day will you open the lecture?\"" },
  { zh: "」乃詐於宮中作土山，開地道向北城。", literal: "\" He then feigned building an earthen hill in the palace and opened a tunnel toward the north city.", idiomatic: "\" He then feigned building an earthen hill in the palace and dug a tunnel toward the north city." },
  { zh: "至千秋門，門者覺地下響，以告澄。", literal: "At Qianqiu Gate the gatekeeper heard underground noise and reported to Cheng.", idiomatic: "At Qianqiu Gate the gatekeeper heard underground noise and told Gao Cheng." },
  { zh: "澄勒兵入宮，見帝，不拜而坐，曰：「陛下何意反？", literal: "Cheng led troops into the palace, saw the emperor, did not bow but sat, and said: \"Your Majesty, what do you mean by rebelling?", idiomatic: "Gao Cheng led troops in, saw the emperor, sat without bowing, and said: \"Your Majesty, what do you mean by rebelling?\"" },
  { zh: "臣父子功存社稷，何負陛下邪！", literal: "Your servant father and son have merit preserving the altars of soil and grain—how have we failed Your Majesty!", idiomatic: "My father and I preserved the altars—how have we failed you!\"" },
  { zh: "此必左右妃嬪輩所為。", literal: "This must be the work of attendants and consorts.", idiomatic: "This must be your attendants and consorts.\"" },
  { zh: "」欲殺胡夫人及李嬪。", literal: "\" He wished to kill Lady Hu and Lady Li.", idiomatic: "\" He meant to kill Lady Hu and Lady Li." },
  { zh: "帝正色曰：「自古唯聞臣反君，不聞君反臣。", literal: "The emperor said sternly: \"From antiquity one has only heard of ministers rebelling against rulers—not rulers rebelling against ministers.", idiomatic: "The emperor said sternly: \"From antiquity one hears of ministers rebelling against rulers—not the reverse.\"" },
  { zh: "王自欲反，何乃責我！", literal: "You, Prince, wish to rebel yourself—why blame me!", idiomatic: "You mean to rebel—why blame me!\"" },
  { zh: "我殺王則社稷安，不殺則滅亡無日，我身且不暇惜，況於妃嬪！", literal: "If I kill you, Prince, the altars will be secure; if I do not kill you, destruction will come in no long day—I do not spare even my own person, how much more consorts!", idiomatic: "Kill you and the altars are secure; spare you and destruction comes—I spare not my own person, how much more consorts!\"" },
  { zh: "必欲弒逆，緩速在王！", literal: "If you must commit regicide, whether soon or late is in the Prince's hands!", idiomatic: "If you must murder your lord, soon or late is in your hands!\"" },
  { zh: "」澄乃下床叩頭，大啼謝罪。", literal: "\" Cheng then left the couch, kowtowed, and wept loudly begging pardon.", idiomatic: "\" Gao Cheng left the couch, kowtowed, and wept for pardon." },
  { zh: "於是酣飲，夜久乃出。", literal: "Then they drank heavily; only late at night did he go out.", idiomatic: "Then they drank heavily until late at night before he left." },
  { zh: "居三日，幽帝於含章堂。", literal: "After three days he imprisoned the emperor in the Hall of Blended Splendor.", idiomatic: "Three days later he imprisoned the emperor in the Hall of Blended Splendor." },
  { zh: "壬辰，烹濟等於市。", literal: "On renchen, Ji and the others were boiled alive in the market.", idiomatic: "On renchen, Ji and the others were boiled alive in the market." },
  { zh: "初，濟少居江東，博學能文。", literal: "At first, when young Ji lived east of the river, he was broadly learned and skilled in letters.", idiomatic: "In his youth Ji had lived east of the river, broadly learned and skilled in letters." },
  { zh: "與上有布衣之舊，知上有大志，然負氣不服，常謂人曰：「會於盾鼻上磨墨檄之。", literal: "He had old ties with the emperor as commoners; knowing the emperor's great ambition, yet proud in spirit and unwilling to yield, he often told men, \"I shall grind ink on the boss of his shield to draft a summons against him.", idiomatic: "He had known the Liang emperor as a commoner and saw his great ambition, yet pride kept him from yielding; he often said, \"I shall grind ink on the boss of his shield to draft a summons against him." },
  { zh: "」上甚不平。", literal: "\" The emperor was greatly displeased.", idiomatic: "\" The Liang emperor was greatly displeased." },
  { zh: "及即位，或薦之於上，上曰：「人雖有才，亂俗好反，不可用也。", literal: "When he took the throne, some recommended Ji to him; the emperor said, \"Though the man has talent, he disorders custom and loves rebellion—he cannot be used.", idiomatic: "When he took the throne, some recommended Ji; the Liang emperor said, \"He has talent, but he disorders custom and loves rebellion—he cannot be used." },
  { zh: "」濟上書諫上崇信佛法、為塔寺奢費，上大怒，欲集朝眾斬之；", literal: "\" Ji memorialized against the emperor's faith in Buddhism and extravagant spending on pagodas and temples; the emperor was furious and wished to gather the court and behead him;", idiomatic: "\" Ji memorialized against Buddhist faith and lavish pagodas; the Liang emperor was furious and wished to gather the court and behead him;" },
  { zh: "朱異密告之，濟逃奔東魏。", literal: "Zhu Yi secretly warned him, and Ji fled to Eastern Wei.", idiomatic: "Zhu Yi warned him in secret, and Ji fled to Eastern Wei." },
  { zh: "澄為中書監，欲用濟為侍讀，獻武王曰：「我愛濟，欲全之，故不用濟。", literal: "Cheng was Director of the Secretariat and wished to make Ji a lecturing attendant; the King of Xianwu said, \"I love Ji and wish to preserve him, and therefore will not use Ji.", idiomatic: "Gao Cheng was Director of the Secretariat and wished to make Ji a lecturing attendant; the King of Xianwu said, \"I love Ji and wish to preserve him, and therefore will not use him." },
  { zh: "濟入宮，必敗。", literal: "If Ji enters the palace, he is sure to fail.", idiomatic: "If Ji enters the palace, he is sure to fail." },
  { zh: "」澄固請，乃許之。", literal: "\" Cheng pressed hard, and permission was granted.", idiomatic: "\" Gao Cheng pressed hard, and permission was granted." },
  { zh: "及敗，侍中楊遵彥謂之曰：「衰暮何苦復爾？", literal: "When he failed, Palace Attendant Yang Zunyan said to him, \"In your declining years, why torment yourself so?", idiomatic: "When he failed, Palace Attendant Yang Zunyan said, \"In your declining years, why torment yourself so?" },
  { zh: "」濟曰：「壯氣在耳！", literal: "\" Ji said, \"My bold spirit is still in my ears!", idiomatic: "\" Ji said, \"My bold spirit is still in my ears!" },
  { zh: "」因下辨曰：「自傷年紀摧頹，功名不立，故欲挾天子，誅權臣。", literal: "\" He then submitted his defense, saying, \"Grieving that my years are broken and my fame unestablished, I wished to seize the Son of Heaven and execute the power-holder.", idiomatic: "\" He submitted his defense: \"Grieving that my years are broken and fame unestablished, I wished to seize the Son of Heaven and execute the power-holder." },
  { zh: "」澄欲宥其死，親問之曰：「荀公何意反？", literal: "\" Cheng wished to spare his life and asked him in person, \"Director Xun, what meant you by rebellion?", idiomatic: "\" Gao Cheng wished to spare him and asked in person, \"Director Xun, what meant you by rebellion?" },
  { zh: "」濟曰：「奉詔誅高澄，何謂反！", literal: "\" Ji said, \"I obeyed an edict to execute Gao Cheng—how is that rebellion!", idiomatic: "\" Ji said, \"I obeyed an edict to execute Gao Cheng—how is that rebellion!" },
  { zh: "」有司以濟老病，鹿車載詣東市，並焚之。", literal: "\" The authorities, because Ji was old and ill, carried him in a deer cart to the eastern market and burned him as well.", idiomatic: "\" Because Ji was old and ill, the authorities carried him in a deer cart to the eastern market and burned him." },
  { zh: "澄疑咨議溫子升知瑾等謀，方使之作獻武王碑，既成，餓於晉陽獄，食弊襦而死。", literal: "Cheng suspected Consultant Wen Zisheng of knowing Jin and the others' plot; he was just then having him compose the King of Xianwu's stele inscription—when it was done, he starved him in Jinyang prison, and he died eating ragged inner garments.", idiomatic: "Gao Cheng suspected Consultant Wen Zisheng of knowing the plot; he was having him compose the King of Xianwu's stele—when it was done, he starved him in Jinyang prison, and he died eating ragged inner garments." },
  { zh: "棄屍路隅，沒其家口，太尉長史宋游道收葬之。", literal: "His corpse was cast by the roadside and his household confiscated; Grand Commandant Chief Clerk Song Youdao gathered and buried him.", idiomatic: "His corpse was cast by the roadside and his household confiscated; Chief Clerk Song Youdao of the Grand Commandant gathered and buried him." },
  { zh: "澄謂游道曰：「吾近書與京師諸貴，論及朝士，以卿僻於朋黨，將為一病。", literal: "Cheng told Youdao, \"I lately wrote the nobles of the capital about court gentlemen, saying that you are aloof from faction and that would be a fault.", idiomatic: "Gao Cheng told Youdao, \"I lately wrote the capital nobles about court gentlemen, saying you were aloof from faction and that would be a fault." },
  { zh: "今乃知卿真是重故舊、尚節義之人，天下人代卿怖者，是不知吾心也。", literal: "Now I know you truly honor old ties and value integrity; those in the realm who fear for you do not know my heart.", idiomatic: "Now I know you truly honor old ties and value integrity; those who fear for you do not know my heart." },
  { zh: "」九月，辛丑，澄還晉陽。", literal: "\" In the ninth month, on xinchou, Cheng returned to Jinyang.", idiomatic: "\" In the ninth month, on xinchou, Gao Cheng returned to Jinyang." },
  { zh: "上命蕭淵明堰泗水於寒山以灌彭城，俟得彭城，乃進軍與侯景掎角。", literal: "The emperor ordered Xiao Yuanming to dam the Si River at Cold Mountain to flood Pengcheng; when Pengcheng was taken, he would advance and coordinate with Hou Jing.", idiomatic: "The Liang emperor ordered Xiao Yuanming to dam the Si at Cold Mountain to flood Pengcheng; when Pengcheng fell, he would advance and coordinate with Hou Jing." },
  { zh: "癸卯，淵明軍於寒山，去彭城十八里，斷流立堰。", literal: "On guimao, Yuanming encamped at Cold Mountain, eighteen li from Pengcheng, cut the flow, and raised a dam.", idiomatic: "On guimao, Yuanming encamped at Cold Mountain, eighteen li from Pengcheng, cut the flow, and raised a dam." },
  { zh: "侍中羊侃監作堰，再旬而成。", literal: "Palace Attendant Yang Kan supervised the dam; in twenty days it was done.", idiomatic: "Palace Attendant Yang Kan supervised the dam; in twenty days it was done." },
  { zh: "東魏徐州刺史太原王則嬰城固守，侃勸淵明乘水攻彭城，不從。", literal: "Eastern Wei's Xuzhou inspector Wang Ze of Taiyuan shut the city and held firm; Kan urged Yuanming to attack Pengcheng on the flood and he would not.", idiomatic: "Wang Ze of Taiyuan, Eastern Wei's Xuzhou inspector, shut the city and held firm; Yang Kan urged Yuanming to attack on the flood, and he would not." },
  { zh: "諸將與淵明議軍事，淵明不能對，但云「臨時制宜」。", literal: "The generals discussed military affairs with Yuanming; he could not answer, but only said, \"Adapt to the moment.\"", idiomatic: "The generals discussed military affairs with Yuanming; he could not answer, but only said, \"Adapt to the moment.\"" },
  { zh: "冬，十一月，魏丞相泰從魏主狩於歧陽。", literal: "In winter, the eleventh month, Wei Chancellor Tai followed the Wei ruler on a hunt at Qiyang.", idiomatic: "In winter, the eleventh month, Yuwen Tai followed the Wei emperor on a hunt at Qiyang." },
  { zh: "東魏大將軍澄使大都督高岳救彭城，欲以金門郡公潘樂為副。", literal: "Eastern Wei Grand General Cheng sent Grand Commander Gao Yue to rescue Pengcheng and wished to make Marquis of Jinmen Pan Le his deputy.", idiomatic: "Gao Cheng sent Grand Commander Gao Yue to rescue Pengcheng and wished to make Marquis of Jinmen Pan Le his deputy." },
  { zh: "陳元康曰：「樂緩於機變，不如慕容紹宗；", literal: "Chen Yuankang said, \"Le is slow in opportune change—not the equal of Murong Shaozong;", idiomatic: "Chen Yuankang said, \"Pan Le is slow to seize opportunity—not the equal of Murong Shaozong;" },
  { zh: "且先王之命也。", literal: "moreover it was the late king's command.", idiomatic: "moreover it was the late king's command." },
  { zh: "公但推赤心於斯人，景不足憂也。", literal: "My lord need only give open heart to this man, and Jing is no cause for worry.", idiomatic: "Give him your open heart, and Hou Jing is no cause for worry." },
  { zh: "」時紹宗在外，澄欲召見之，恐其驚叛；", literal: "\" Shaozong was then abroad; Cheng wished to summon him but feared alarming him into rebellion;", idiomatic: "\" Shaozong was abroad; Gao Cheng wished to summon him but feared alarming him into rebellion;" },
  { zh: "元康曰：「紹宗知元康特蒙顧待，新使人來餉金；", literal: "Yuankang said, \"Shaozong knows Yuankang is specially favored; he lately sent men with gifts of gold;", idiomatic: "Yuankang said, \"Shaozong knows I am specially favored; he lately sent men with gifts of gold;" },
  { zh: "元康欲安其意，受之而厚答其書，保無異也。", literal: "Yuankang wishes to set his mind at ease—accept and reply generously to his letter, and he will surely not differ.", idiomatic: "I will set his mind at ease—accept and reply generously, and he will not rebel." },
  { zh: "」乙酉，以紹宗為東南道行台，與岳、樂偕行。", literal: "\" On yiyou, Shaozong was made Mobile Headquarters of the Southeast Route and marched with Yue and Le.", idiomatic: "\" On yiyou, Murong Shaozong was made Mobile Headquarters of the Southeast Route and marched with Yue and Pan Le." },
  { zh: "初，景聞韓軌來，曰：「啖豬腸兒何能為！", literal: "At first, when Jing heard Han Gui was coming, he said, \"What can that pig-gut eater do!", idiomatic: "At first, when Hou Jing heard Han Gui was coming, he said, \"What can that pig-gut eater do!" },
  { zh: "」聞高岳來，曰：「兵精人凡。", literal: "\" When he heard Gao Yue was coming, he said, \"Troops keen, the man ordinary.", idiomatic: "\" When he heard Gao Yue was coming, he said, \"Troops keen, the man ordinary." },
  { zh: "」諸將無不為所輕者。", literal: "\" None of the generals escaped his contempt.", idiomatic: "\" None of the generals escaped his contempt." },
  { zh: "及聞紹宗來，叩鞍有懼色，曰：「誰教鮮卑兒解遣紹宗來！", literal: "When he heard Shaozong was coming, he beat the saddle with fear in his face and said, \"Who taught the Xianbei stripling to send Shaozong!", idiomatic: "When he heard Shaozong was coming, he beat the saddle in fear and said, \"Who taught the Xianbei stripling to send Shaozong!" },
  { zh: "若然，高王定未死邪？", literal: "If so, the King of Gao must surely not be dead!", idiomatic: "If so, the King of Gao must still be alive!" },
  { zh: "澄以廷尉卿杜弼為軍司，攝行台左丞，臨發，問以政事之要、可為戒者，使錄一二條。", literal: "Cheng made Court Director Du Bi army secretary and acting left director of the mobile headquarters; on departure he asked the essentials of government and what might serve as warnings, and had him record one or two items.", idiomatic: "Gao Cheng made Court Director Du Bi army secretary and acting left director of the mobile headquarters; on departure he asked the essentials of government and what might serve as warnings, and had him record one or two items." },
  { zh: "弼請口陳之，曰：「天下大務，莫過賞罰。", literal: "Bi asked to state them orally and said, \"Of the great affairs under Heaven, none surpass reward and punishment.", idiomatic: "Bi asked to state them orally: \"Of the great affairs under Heaven, none surpass reward and punishment." },
  { zh: "賞一人使天下之人喜，罰一人使天下之人懼，苟二事不失，自然盡美。", literal: "Reward one man and all under Heaven rejoice; punish one man and all under Heaven fear—if these two are not lost, perfection follows of itself.", idiomatic: "Reward one man and all under Heaven rejoice; punish one man and all under Heaven fear—hold to these two and perfection follows of itself." },
  { zh: "」澄大悅，曰：「言雖不多，於理甚要。", literal: "\" Cheng was greatly pleased and said, \"The words are few, but in principle most essential.", idiomatic: "\" Gao Cheng was greatly pleased and said, \"Few words, but most essential in principle." },
  { zh: "紹宗帥眾十萬據橐駝峴。", literal: "Shaozong led a hundred thousand men and held Camel Neck Pass.", idiomatic: "Murong Shaozong led a hundred thousand men and held Camel Neck Pass." },
  { zh: "羊侃勸貞陽侯淵明乘其遠來擊之，不從，旦日，又勸出戰，亦不從；", literal: "Yang Kan urged Prince Yuanming of Zhenyang to strike while the enemy was still far; he would not. At dawn he urged battle again, and again he would not;", idiomatic: "Yang Kan urged Prince Yuanming of Zhenyang to strike while the enemy was still far; he would not. At dawn he urged battle again, and again he would not;" },
  { zh: "侃乃帥所領出屯堰上。", literal: "Kan then led his own troops out to camp on the dam.", idiomatic: "Yang Kan then led his own troops out to camp on the dam." },
  { zh: "丙午，紹宗至城下，引步騎萬人攻潼州刺史郭鳳營，矢下如雨。", literal: "On bingwu, Shaozong reached the wall, led ten thousand foot and horse against Tongzhou inspector Guo Feng's camp, and arrows fell like rain.", idiomatic: "On bingwu, Shaozong reached the wall, led ten thousand foot and horse against Guo Feng's camp, and arrows fell like rain." },
  { zh: "淵明醉，不能起，命諸將救之，皆不敢出。", literal: "Yuanming was drunk and could not rise; he ordered the generals to rescue the camp, and none dared go out.", idiomatic: "Yuanming was drunk and could not rise; he ordered the generals to rescue the camp, and none dared go out." },
  { zh: "北兗州刺史胡貴孫謂譙州刺史趙伯超曰：「吾屬將兵而來，本欲何為，今遇敵而不戰乎？", literal: "North Yanzhou inspector Hu Guisun said to Qiao inspector Zhao Bochao, \"We came leading troops—what was that for? Now we meet the enemy and will not fight?", idiomatic: "Hu Guisun, inspector of North Yanzhou, said to Zhao Bochao, inspector of Qiao, \"We came leading troops—what for? Now we meet the enemy and will not fight?" },
  { zh: "」伯超不能對。", literal: "\" Bochao could not answer.", idiomatic: "\" Bochao could not answer." },
  { zh: "貴孫獨帥麾下與東魏戰，斬首二百級。", literal: "Guisun alone led his followers to fight Eastern Wei and took two hundred heads.", idiomatic: "Guisun alone led his followers against Eastern Wei and took two hundred heads." },
  { zh: "伯超擁眾數千不敢救，謂其下曰：「虜盛如此，與戰必敗，不如全軍早歸，可以免罪。", literal: "Bochao held several thousand men and dared not rescue them; he told his men, \"The foe is so strong that battle is sure defeat—better bring the whole army home early and escape punishment.", idiomatic: "Bochao held several thousand men and dared not rescue them; he told his men, \"The foe is so strong that battle means defeat—better bring the whole army home early and escape punishment." },
  { zh: "」皆曰：「善！", literal: "\" All said, \"Good!", idiomatic: "\" All said, \"Good!" },
  { zh: "」遂遁還。", literal: "\" They then fled back.", idiomatic: "\" They then fled back." },
  { zh: "初，侯景常戒梁人曰：「逐北勿過二里。", literal: "At first, Hou Jing often warned the men of Liang, \"In pursuit northward, do not go past two li.", idiomatic: "At first, Hou Jing often warned the men of Liang, \"In pursuit northward, do not go past two li." },
  { zh: "」紹宗將戰，以梁人輕悍，恐其眾不能支，一一引將卒謂之曰：「我當陽退，誤吳兒使前，爾擊其背。", literal: "\" As Shaozong was about to fight, fearing the men of Liang were light and fierce and his host could not hold, he took each officer and soldier aside and said, \"I shall feign retreat in daylight, lure the Wu lads forward, and you strike their backs.", idiomatic: "\" As Shaozong was about to fight, fearing the men of Liang were light and fierce, he told each officer and soldier, \"I shall feign retreat in daylight, lure the Wu lads forward, and you strike their backs." },
  { zh: "」東魏兵實敗走，梁人不用景言，乘勝深入。", literal: "\" Eastern Wei troops truly broke and fled; the men of Liang did not use Jing's words and pressed the victory deep.", idiomatic: "\" Eastern Wei troops truly broke and fled; the men of Liang ignored Hou Jing's warning and pressed deep in victory." },
  { zh: "魏將卒以紹宗之言為信，爭共掩擊之，梁兵大敗，貞陽侯淵明及胡貴孫、趙伯超等皆為東魏所虜，失亡士卒數萬人。", literal: "Wei officers and soldiers trusted Shaozong's words and vied to ambush them; Liang troops were routed in great defeat, Prince Yuanming of Zhenyang and Hu Guisun, Zhao Bochao, and others were all captured by Eastern Wei, and tens of thousands of soldiers were lost.", idiomatic: "Eastern Wei officers and soldiers trusted Shaozong's words and vied to ambush them; Liang troops were routed, Prince Yuanming and Guisun, Bochao, and others were captured, and tens of thousands were lost." },
  { zh: "羊侃結陳徐還。", literal: "Yang Kan gathered his array and returned slowly.", idiomatic: "Yang Kan gathered his array and returned slowly." },
  { zh: "上方晝寢，宦者張僧胤白朱異啟事，上駭之，遽起升輿，至文德殿閣。", literal: "The emperor was napping by day; eunuch Zhang Sengyin told Zhu Yi to report business; the emperor was startled, rose hastily into his carriage, and went to the gallery of the Hall of Civil Virtue.", idiomatic: "The Liang emperor was napping by day; eunuch Zhang Sengyin told Zhu Yi to report business; the emperor was startled, rose into his carriage, and went to the gallery of the Hall of Civil Virtue." },
  { zh: "異曰：「寒山失律。", literal: "Yi said, \"Cold Mountain has lost its measure.", idiomatic: "Zhu Yi said, \"Cold Mountain has lost its measure." },
  { zh: "」上聞之，恍然將墜床。", literal: "\" When the emperor heard it, he was dazed and nearly fell from the couch.", idiomatic: "\" When the Liang emperor heard it, he was dazed and nearly fell from the couch." },
  { zh: "僧胤扶而就坐，乃歎曰：「吾得無復為晉家乎！", literal: "Sengyin supported him to a seat, and he sighed, \"Must I not become the house of Jin again!", idiomatic: "Sengyin supported him to a seat, and he sighed, \"Must I not become the house of Jin again!" },
  { zh: "郭鳳退保潼州，慕容紹宗進圍之。", literal: "Guo Feng withdrew to hold Tong province; Murong Shaozong advanced and besieged him.", idiomatic: "Guo Feng withdrew to hold Tong province; Murong Shaozong advanced and besieged him." },
  { zh: "十二月，甲子朔，鳳棄城走。", literal: "In the twelfth month, on the first day jiazi, Feng abandoned the city and fled.", idiomatic: "In the twelfth month, on the first day jiazi, Feng abandoned the city and fled." },
  { zh: "東魏使軍司杜弼作檄移梁朝曰：「皇家垂統，光配彼天，唯彼吳、越，獨阻聲教。", literal: "Eastern Wei had army secretary Du Bi compose a proclamation to the Liang court, saying, \"The imperial house extends its line, its glory matching that Heaven—only Wu and Yue alone resist our voice and teaching.", idiomatic: "Eastern Wei had army secretary Du Bi compose a proclamation to the Liang court: \"The imperial house extends its line, its glory matching Heaven—only Wu and Yue resist our teaching." },
  { zh: "元首懷止戈之心，上宰薄兵車之命，遂解縶南冠，喻以好睦。", literal: "The sovereign harbored a heart to halt the spear; the chief minister lightened the chariot of war—thereupon southern captives were unbound and shown friendship and peace.", idiomatic: "The sovereign harbored a heart to halt the spear; the chief minister lightened the chariot of war—captives were unbound and shown friendship." },
  { zh: "雖嘉謀長算，爰自我始，罷戰息民，彼獲其利。", literal: "Though fine counsel and long plans began with us, halting war and resting the people, they gained the profit.", idiomatic: "Though fine counsel began with us, halting war and resting the people, they gained the profit." },
  { zh: "侯景豎子，自生猜貳，遠托關、隴，依憑奸偽，逆主定君臣之分，偽相結兄弟之親，豈曰無恩，終成難養，俄而易慮，親尋干戈。", literal: "Hou Jing, that base stripling, bred suspicion of himself, entrusted himself afar to Guan and Long, relied on treacherous falsehood, set lord and subject against his master, feigned brotherhood with a minister—was it said there was no grace? In the end he proved hard to keep; soon he changed his mind and took up arms in person.", idiomatic: "Hou Jing, that base stripling, bred suspicion, fled to Guan and Long, relied on treachery, set lord against master, feigned brotherhood with a minister—was there no grace? In the end he proved hard to keep; soon he took up arms." },
  { zh: "釁暴惡盈，側首無托，以金陵逋逃之藪，江南流寓之地，甘辭卑禮，進孰圖身，詭言浮說，抑可知矣。", literal: "His outrage overflowed and wickedness was full; he turned his head with nowhere to lean, taking Jinling, lair of fugitives, and the lands of Jiangnan where exiles dwell—sweet words and humble rites, advancing to seize his own body—his deceitful speech and floating claims may well be known.", idiomatic: "His outrage overflowed; he turned his head with nowhere to lean, taking Jinling, lair of fugitives, and Jiangnan, land of exiles—sweet words and humble rites to save himself; his deceit may well be known." },
  { zh: "而偽朝大小，幸災忘義，主荒於上，臣蔽於下，連結奸惡，斷絕鄰好，徵兵保境，縱盜侵國。", literal: "Yet great and small of the false court rejoiced in disaster and forgot righteousness; the ruler was lost above, ministers screened below; they linked with the wicked, cut off neighborly peace, raised troops to guard borders, and let robbers invade the state.", idiomatic: "Yet great and small of the false court rejoiced in disaster; the ruler was lost above, ministers screened below; they linked with the wicked, cut off neighbors, raised troops, and let robbers invade." },
  { zh: "蓋物無定方，事無定勢，或乘利而受害，或因得而更失。", literal: "Things have no fixed direction, affairs no fixed momentum—sometimes one rides profit into harm, sometimes gain becomes loss again.", idiomatic: "Things have no fixed direction—sometimes profit becomes harm, sometimes gain becomes loss." },
  { zh: "是以吳侵齊境，遂得句踐之師，趙納韓地，終有長平之役。", literal: "Thus Wu invaded Qi and thereby won Goujian's army; Zhao took Han lands and in the end met the battle of Changping.", idiomatic: "Wu invaded Qi and thereby won Goujian's army; Zhao took Han lands and met Changping." },
  { zh: "矧乃鞭撻疲民，侵軼徐部，築壘擁川，捨舟徼利。", literal: "How much more when they lash the weary people, raid Xu province, build ramparts to choke the rivers, and abandon boats to snatch profit!", idiomatic: "How much more when they lash the weary people, raid Xu, build ramparts to choke the rivers, and abandon boats to snatch profit!" },
  { zh: "是以援枹秉麾之將，拔距投石之士，含怒作色，如赴私仇。", literal: "Hence the generals who beat the drum and hold the banner, the soldiers who wrestle and cast stones, bear anger on their faces as if to a private feud.", idiomatic: "Hence generals who beat the drum and hold the banner, soldiers who wrestle and cast stones, bear anger as for a private feud." },
  { zh: "彼連營擁眾，依山傍水，舉螳□良之斧，被蛣蜣之甲，當窮轍以待輪，坐積薪而候燎。", literal: "They mass camps and crowd hosts, lean on mountains and hug the water, raise mantis-arm axes, don dung-beetle armor, wait in a broken rut for the wheel, sit on piled kindling for the flame.", idiomatic: "They mass camps and crowd hosts, lean on mountains and hug the water, raise mantis-arm axes, don dung-beetle armor, wait in a broken rut for the wheel, sit on piled kindling for the flame." },
  { zh: "及鋒刃暫交，埃塵且接，已亡戟棄戈，土崩瓦解，掬指舟中，衿甲鼓下，同宗異姓，縲紲相望。", literal: "When blades briefly met and dust rose between them, halberds were already lost and spears cast aside—the earth crumbled and walls gave way; fingers were cupped in boats, armor at the breast under drums; kin of one clan and different surnames, bonds and fetters in sight of one another.", idiomatic: "When blades met and dust rose, halberds were lost and spears cast aside—earth crumbled and walls gave way; fingers cupped in boats, armor at the breast under drums; kin and strangers, bonds in sight of one another." },
  { zh: "曲直既殊，強弱不等，獲一人而失一國，見黃雀而忘深阱，智者所不為，仁者所不向。", literal: "Right and wrong were already different, strong and weak unequal—to gain one man and lose a state, see the yellow sparrow and forget the deep pit—what the wise do not do, what the humane do not face.", idiomatic: "Right and wrong differed, strong and weak were unequal—to gain one man and lose a state, see the yellow sparrow and forget the deep pit—what the wise do not do, what the humane do not face." },
  { zh: "誠既往之難逮，猶將來之可追。", literal: "Truly the past is hard to reach again, yet the future may still be pursued.", idiomatic: "The past is hard to reach again, yet the future may still be pursued." },
  { zh: "侯景以鄙俚之夫，遭風雲之會，位班三事，邑啟萬家，揣身量分，久當止足。", literal: "Hou Jing, a vulgar fellow, met the hour of wind and cloud, ranked among the Three Dignities, fiefs opened to ten thousand households—measuring body and portion, he should long since have stopped.", idiomatic: "Hou Jing, a vulgar fellow, met the hour of wind and cloud, ranked among the Three Dignities, fiefs to ten thousand households—measuring body and portion, he should long since have stopped." },
  { zh: "而周章向背，離披不已，夫豈徒然，意亦可見。", literal: "Yet he wavered to and fro without cease—was it for nothing? His intent may be seen.", idiomatic: "Yet he wavered to and fro without cease—was it for nothing? His intent may be seen." },
  { zh: "彼乃授之以利器，誨之以慢藏，使其勢得容奸，時堪乘便。", literal: "They gave him sharp tools and taught him careless keeping, letting his power harbor treachery and the moment be seized for advantage.", idiomatic: "They gave him sharp tools and taught him careless keeping, letting his power harbor treachery and the moment be seized." },
  { zh: "今見南風不競，天亡有征，老賊奸謀，將復作矣。", literal: "Now the southern wind does not contend; Heaven's ruin has its sign; the old villain's treacherous plot will act again.", idiomatic: "Now the southern wind does not contend; Heaven's ruin has its sign; the old villain's plot will act again." },
  { zh: "然推堅強者難為功，摧枯朽者易為力。", literal: "Yet pushing the hard and strong is hard to accomplish; breaking the withered and rotten is easy in strength.", idiomatic: "Pushing the hard and strong is hard; breaking the withered and rotten is easy." },
  { zh: "計其雖非孫、吳猛將，燕、趙精兵，猶是久涉行陳，曾習軍旅，豈同剽輕之師，不比危脆之眾。", literal: "Counting that though they are not fierce generals of Sun and Wu, nor picked troops of Yan and Zhao, they are still long seasoned in the ranks and practiced in armies—how are they like a light raiding host or a brittle, perilous crowd?", idiomatic: "Though they are not Sun and Wu's fierce generals nor Yan and Zhao's picked troops, they are long seasoned in the ranks—how are they like a light raiding host or a brittle crowd?" },
  { zh: "拒此則作氣不足，攻彼則為勢有餘，終恐尾大於身，踵粗於股，倔強不掉，狼戾難馴。", literal: "Resist these and their fighting spirit falls short; attack those and momentum has surplus—in the end one fears tail larger than body, heel thicker than thigh, stubborn and unyielding, savage and hard to tame.", idiomatic: "Resist these and spirit falls short; attack those and momentum has surplus—in the end tail outgrows body, heel outgrows thigh, stubborn and savage, hard to tame." },
  { zh: "呼之則反速而釁小，不征則叛遲而禍大。", literal: "Summon them and they rebel quickly with small outrage; do not campaign and rebellion is slow but calamity great.", idiomatic: "Summon them and they rebel quickly with small outrage; do not campaign and rebellion is slow but calamity great." },
  { zh: "會應遙望廷尉，不肯為臣，自據淮南，亦欲稱帝。", literal: "Soon he will gaze from afar at the Court Director, refuse to be minister, hold Huainan himself, and wish to style himself emperor.", idiomatic: "Soon he will gaze at the Court Director, refuse to be minister, hold Huainan, and wish to style himself emperor." },
  { zh: "但恐楚國亡猿，禍延林木，城門失火，殃及池魚。", literal: "Yet one fears that when Chu lost its ape, disaster spread to the woods; when the gate caught fire, the fish in the pool suffered.", idiomatic: "Yet when Chu lost its ape, disaster spread to the woods; when the gate caught fire, the fish in the pool suffered." },
  { zh: "橫使江、淮士子，荊、揚人物，死亡矢石之下，夭折霧露之中。", literal: "In vain Jiang and Huai scholars, Jing and Yang men of note, die under arrows and stones and perish young in mist and dew.", idiomatic: "In vain Jiang and Huai scholars, Jing and Yang men of note, die under arrows and stones and perish young in mist and dew." },
  { zh: "彼梁主，操行無聞，輕險有素，射雀論功，盪舟稱力，年既老矣，耄又及之，政散民流，禮崩樂壞。", literal: "That Liang ruler—conduct unheard of, frivolity and peril his nature, shooting sparrows to discuss merit, capsizing boats to boast strength—years already old, dotage upon him; government scattered, people adrift, rites collapsed and music ruined.", idiomatic: "That Liang ruler—conduct unheard of, frivolity his nature, shooting sparrows for merit, capsizing boats to boast strength—old, doting; government scattered, people adrift, rites collapsed and music ruined." },
  { zh: "加以用捨乖方，廢立失所，矯情動俗，飾智驚愚，毒螫滿懷，妄敦戒業，躁競盈胸，謬治清淨。", literal: "Add to this use and dismissal contrary to measure, establishment and removal out of place, feigned feeling to move custom, adorned wit to startle fools, venom stings filling the breast, vainly urging restraint and karma, rash striving filling the chest, falsely governing purity and stillness.", idiomatic: "Add use and dismissal contrary to measure, establishment out of place, feigned feeling, adorned wit to startle fools, venom in the breast, vain restraint, rash striving in the chest, false purity." },
  { zh: "災異降於上，怨讟興於下，人人厭苦，家家思亂，履霜有漸，堅冰且至。", literal: "Portents descend above, resentment rises below; every man hates his lot, every house thinks of disorder—treading frost has its stages, solid ice is near.", idiomatic: "Portents descend above, resentment rises below; every man hates his lot, every house thinks of disorder—treading frost has its stages, solid ice is near." },
  { zh: "傳險躁之風俗，任輕薄之子孫。", literal: "They pass on reckless, rash custom and entrust frivolous sons and grandsons.", idiomatic: "They pass on reckless custom and entrust frivolous sons and grandsons." },
  { zh: "朋黨路開，兵權在外。", literal: "Faction opens the road; military power lies outside.", idiomatic: "Faction opens the road; military power lies outside." },
  { zh: "必將禍生骨肉，釁起腹心，強弩沖城，長戈指闕；", literal: "Calamity will surely rise from flesh and bone, outrage from the belly and heart; strong crossbows will strike the wall, long spears point at the palace gate;", idiomatic: "Calamity will rise from flesh and bone, outrage from the belly and heart; strong crossbows will strike the wall, long spears point at the palace gate;" },
  { zh: "徒探雀鷇，無救府藏之虛，空請熊蹯，詎延晷刻之命。", literal: "vainly they reach for sparrow fledglings and cannot save the treasury's emptiness; empty they beg for bear paws and cannot extend life by a moment.", idiomatic: "vainly they reach for sparrow fledglings and cannot save the empty treasury; empty they beg for bear paws and cannot extend life by a moment." },
  { zh: "外崩中潰，今實其時。", literal: "Outward collapse and inward breach—now is truly the hour.", idiomatic: "Outward collapse and inward breach—now is truly the hour." },
  { zh: "鷸蚌相持，我乘其弊。", literal: "Snipe and clam hold each other; we ride their exhaustion.", idiomatic: "Snipe and clam hold each other; we ride their exhaustion." },
  { zh: "方使駿騎追風，精甲輝日，四七並列，百萬為群，以轉石之形，為破竹之勢。", literal: "We shall send swift horses chasing the wind, keen armor gleaming in the sun, four and seven arrayed together, a million as one host, the form of rolling stone becoming the momentum of splitting bamboo.", idiomatic: "We shall send swift horses chasing the wind, keen armor gleaming in the sun, hosts arrayed in ranks, a million as one, rolling stone becoming splitting bamboo." },
  { zh: "當使鐘山渡江，青蓋入洛，荊棘生於建業之宮，糜鹿游於姑蘇之館。", literal: "Zhong Mountain shall cross the river, the green-canopied carriage enter Luoyang; brambles shall grow in the palace of Jianye, elk wander in the halls of Gusu.", idiomatic: "Zhong Mountain shall cross the river, the green-canopied carriage enter Luoyang; brambles shall grow in Jianye's palace, elk wander in Gusu's halls." },
  { zh: "但恐革車之所□藺轢，劍騎之所蹂踐，杞梓於焉傾折，竹箭以此摧殘。", literal: "Yet one fears where war chariots crush and trample, where sword and horse tread down— catalpa and zelkova there broken, bamboo and arrow shafts there ruined.", idiomatic: "Yet one fears where war chariots crush and trample, where sword and horse tread down—fine timber broken, bamboo shafts ruined." },
  { zh: "若吳之王孫，蜀之公子，歸款軍門，委命下吏，當即授客卿之秩，特加驃騎之號。", literal: "If princes of Wu and sons of Shu come in submission to the camp gate and entrust their lives to lower officers, they shall at once receive the rank of guest minister and be specially given the title Rapid Cavalry.", idiomatic: "If princes of Wu and sons of Shu come in submission and entrust their lives to lower officers, they shall receive the rank of guest minister and the title Rapid Cavalry." },
  { zh: "凡百君子，勉求多福。", literal: "All you gentlemen, strive to seek much blessing.", idiomatic: "All you gentlemen, strive to seek much blessing." },
  { zh: "」其後梁室禍敗，皆如弼言。", literal: "\" Afterward the house of Liang met disaster and defeat—all as Bi had said.", idiomatic: "\" Afterward the house of Liang met disaster and defeat—all as Du Bi had said." },
  { zh: "侯景圍譙城，不下。", literal: "Hou Jing besieged Qiao city and could not take it.", idiomatic: "Hou Jing besieged Qiao city and could not take it." },
  { zh: "退攻城父，拔之。", literal: "He withdrew and attacked Chengfu and took it.", idiomatic: "He withdrew, attacked Chengfu, and took it." },
  { zh: "壬申，遣其行台左丞王偉等詣建康說上曰：「鄴中文武合謀，召臣共討高澄。", literal: "On renshen, he sent his mobile headquarters left director Wang Wei and others to Jiankang to persuade the emperor, saying, \"Civil and military men at Ye plotted together and summoned me to join in punishing Gao Cheng.", idiomatic: "On renshen, he sent his mobile headquarters left director Wang Wei and others to Jiankang to tell the Liang emperor, \"Civil and military men at Ye plotted together and summoned me to join in punishing Gao Cheng." },
  { zh: "事洩，澄幽元善見於金墉，殺諸元六十餘人。", literal: "The affair leaked; Cheng imprisoned Yuan Shanjian at Jinyong and killed more than sixty of the Yuans.", idiomatic: "The affair leaked; Gao Cheng imprisoned Yuan Shanjian at Jinyong and killed more than sixty of the Yuans." },
  { zh: "河北物情，俱念其主，請立元氏一人以從人望，如此，則陛下有繼絕之名，臣景有立功之效。", literal: "Sentiment in Hebei all yearns for its lord; we ask to establish one of the Yuan clan to follow men's hopes—thus Your Majesty gains the name of continuing a broken line, and your servant Jing the merit of achievement.", idiomatic: "Sentiment in Hebei yearns for its lord; establish one of the Yuan clan to follow men's hopes—thus Your Majesty gains the name of continuing a broken line, and your servant Jing the merit of achievement." },
  { zh: "河之南北，為聖朝之邾、莒；", literal: "North and south of the river shall be Zhu and Ju to the holy court;", idiomatic: "North and south of the river shall be Zhu and Ju to the holy court;" },
  { zh: "國之男女，為大梁之臣妾。", literal: "the men and women of those states, subjects and handmaids of Great Liang.", idiomatic: "its men and women, subjects and handmaids of Great Liang." },
  { zh: "」上以為然，乙亥，下詔以太子舍人元貞為咸陽王，資以兵力，使還北主魏，須渡江，許即位，儀衛以乘輿之副給之。", literal: "\" The emperor thought it so; on yihai he issued an edict making Crown Prince Household Attendant Yuan Zhen Prince of Xianyang, supplying him with troops to return north and rule Wei—once he crossed the river, enthronement was permitted, and guard and escort were given as for the imperial carriage's deputy.", idiomatic: "\" The Liang emperor agreed; on yihai he made Crown Prince Household Attendant Yuan Zhen Prince of Xianyang, supplied him with troops to return north and rule Wei—once he crossed the river, enthronement was permitted, and guard and escort were given as for the imperial carriage's deputy." },
  { zh: "貞，樹之子也。", literal: "Zhen was Shu's son.", idiomatic: "Zhen was the son of Yuan Shu." },
  { zh: "蕭淵明至鄴，東魏主升閶闔門受俘，讓而釋之，送於晉陽，大將軍澄待之甚厚。", literal: "When Xiao Yuanming reached Ye, the Eastern Wei ruler ascended the Gate of Universal Peace to receive the captive, declined and released him, sent him to Jinyang, and Grand General Cheng treated him very generously.", idiomatic: "When Xiao Yuanming reached Ye, the Eastern Wei emperor ascended the Gate of Universal Peace to receive the captive, declined and released him, sent him to Jinyang, and Gao Cheng treated him very generously." },
  { zh: "慕容紹宗引軍擊侯景，景輜重數千兩，馬數千匹，士卒四萬人，退保渦陽。", literal: "Murong Shaozong led troops against Hou Jing; Jing had several thousand baggage carts, several thousand horses, and forty thousand soldiers, and withdrew to hold Woyang.", idiomatic: "Murong Shaozong led troops against Hou Jing; Jing had several thousand baggage carts, several thousand horses, and forty thousand soldiers, and withdrew to hold Woyang." },
  { zh: "紹宗士卒十萬，旗甲耀日，鳴鼓長驅而進。", literal: "Shaozong had a hundred thousand soldiers; banners and armor dazzled the sun; drums sounded as they drove forward at length.", idiomatic: "Shaozong had a hundred thousand soldiers; banners and armor dazzled the sun; drums sounded as they drove forward." },
  { zh: "景使謂之曰：「公等為欲送客，為欲定雌雄邪？", literal: "Jing sent word: \"Are you gentlemen wishing to see guests off, or to decide victor and vanquished?", idiomatic: "Hou Jing sent word: \"Are you wishing to see guests off, or to decide victor and vanquished?" },
  { zh: "」紹宗曰：「欲與公決勝負。", literal: "\" Shaozong said, \"I wish to settle victory and defeat with you.", idiomatic: "\" Shaozong said, \"I wish to settle victory and defeat with you." },
  { zh: "」遂順風布陳。", literal: "\" He then deployed his array with the wind.", idiomatic: "\" He then deployed his array with the wind." },
  { zh: "景閉壘，俟風止乃出。", literal: "Jing shut the ramparts and waited for the wind to stop before coming out.", idiomatic: "Hou Jing shut the ramparts and waited for the wind to stop before coming out." },
  { zh: "紹宗曰：「侯景多詭計，好乘人背。", literal: "Shaozong said, \"Hou Jing has many deceitful schemes and likes to strike men's backs.", idiomatic: "Shaozong said, \"Hou Jing has many deceitful schemes and likes to strike from behind." },
  { zh: "」使備之，果如其言。", literal: "\" He had them prepare, and it was indeed as he said.", idiomatic: "\" He had them prepare, and it was indeed as he said." },
  { zh: "景命戰士皆被短甲，執短刀，入東魏陳，但低視，斫人脛馬足。", literal: "Jing ordered his warriors all to wear short armor, hold short blades, enter the Eastern Wei array, look only downward, and hack men's shins and horses' legs.", idiomatic: "Hou Jing ordered his warriors to wear short armor, hold short blades, enter the Eastern Wei array, look only downward, and hack men's shins and horses' legs." },
  { zh: "東魏兵遂敗，紹宗墜馬，儀同三司劉豐生被傷，顯州刺史張遵業為景所擒。", literal: "Eastern Wei troops were routed; Shaozong fell from his horse; Equal in Honor to the Three Dukes Liu Fengsheng was wounded; Xianzhou inspector Zhang Zunye was captured by Jing.", idiomatic: "Eastern Wei troops were routed; Shaozong fell from his horse; Liu Fengsheng, Equal to the Three Dukes, was wounded; Zhang Zunye, inspector of Xian, was captured by Hou Jing." },
  { zh: "紹宗、豐生俱奔譙城，裨將斛律光、張恃顯尤之，紹宗曰：「吾戰多矣，未見如景之難克者也。", literal: "Shaozong and Fengsheng both fled to Qiao city; subordinate generals Hulu Guang and Zhang Shixian blamed him; Shaozong said, \"I have fought many battles and never seen one so hard to overcome as Jing.", idiomatic: "Shaozong and Fengsheng both fled to Qiao city; subordinate generals Hulu Guang and Zhang Shixian blamed him; Shaozong said, \"I have fought many battles and never seen one so hard to overcome as Hou Jing." },
  { zh: "君輩試犯之！", literal: "You gentlemen, try attacking him!", idiomatic: "You gentlemen, try attacking him!" },
  { zh: "」光等被甲將出，紹宗戒之曰：「勿渡渦水。", literal: "\" Guang and the others donned armor and were about to go out; Shaozong warned them, \"Do not cross the Wo River.", idiomatic: "\" Guang and the others donned armor and were about to go out; Shaozong warned them, \"Do not cross the Wo River." },
  { zh: "」二人軍於水北，光輕騎射之。", literal: "\" The two encamped north of the water; Guang with light horse shot at him.", idiomatic: "\" The two encamped north of the water; Guang with light horse shot at him." },
  { zh: "景臨渦水謂光曰：「爾求勳而來，我懼死而去。", literal: "Jing stood by the Wo River and said to Guang, \"You came seeking merit; I fear death and would leave.", idiomatic: "Hou Jing stood by the Wo River and said to Guang, \"You came seeking merit; I fear death and would leave." },
  { zh: "我，汝之父友，何為射我？", literal: "I am your father's friend—why shoot me?", idiomatic: "I am your father's friend—why shoot me?" },
  { zh: "汝豈自解不渡水南？", literal: "Do you not understand for yourself not to cross south of the water?", idiomatic: "Do you not understand for yourself not to cross south of the water?" },
  { zh: "慕容紹宗教汝也！", literal: "Murong Shaozong taught you that!", idiomatic: "Murong Shaozong taught you that!" },
  { zh: "」光無以應。", literal: "\" Guang had nothing to answer.", idiomatic: "\" Guang had nothing to answer." },
  { zh: "景使其徒田遷射光馬，洞胸；", literal: "Jing had his follower Tian Qian shoot Guang's horse, piercing its chest;", idiomatic: "Hou Jing had his follower Tian Qian shoot Guang's horse, piercing its chest;" },
  { zh: "光易馬隱樹，又中之，退入於軍。", literal: "Guang changed horses and hid behind a tree; he was hit again and withdrew into the army.", idiomatic: "Guang changed horses and hid behind a tree; he was hit again and withdrew into the army." },
  { zh: "景擒恃顯，既而捨之。", literal: "Jing captured Shixian and then released him.", idiomatic: "Hou Jing captured Shixian and then released him." },
  { zh: "光走入譙城，紹宗曰：「今定何如，而尤我也！", literal: "Guang ran into Qiao city; Shaozong said, \"Now how is it, that you blame me!", idiomatic: "Guang ran into Qiao city; Shaozong said, \"Now how is it, that you blame me!" },
  { zh: "」光，金之子也。", literal: "\" Guang was Jin's son.", idiomatic: "\" Guang was the son of Hulu Jin." },
  { zh: "開府儀同三司段韶夾渦而軍，潛於上風縱火，景帥騎入水，出而卻走，草濕，火不復然。", literal: "Opening the Mansion Equal in Honor to the Three Dukes Duan Shao encamped on both sides of the Wo; secretly he set fire upwind; Jing led cavalry into the water, came out and retreated—the grass was wet and the fire would not catch again.", idiomatic: "Duan Shao, Opening the Mansion Equal to the Three Dukes, encamped on both sides of the Wo; secretly he set fire upwind; Hou Jing led cavalry into the water, came out and retreated—the grass was wet and the fire would not catch." },
  { zh: "魏岐州久經喪亂，刺史鄭穆初到，有戶三千，穆撫循安集，數年之間，至四萬餘戶，考績為諸州之最；", literal: "Wei's Qi province had long suffered disorder; when inspector Zheng Mu first arrived there were three thousand households; Mu comforted and settled them, and within several years there were more than forty thousand households; his assessment ranked first among the provinces;", idiomatic: "Qi province of Western Wei had long suffered disorder; when inspector Zheng Mu first arrived there were three thousand households; Mu comforted and settled them, and within several years there were more than forty thousand; his assessment ranked first among the provinces;" },
  { zh: "丞相泰擢穆為京兆尹。", literal: "Chancellor Tai promoted Mu to Governor of the Capital District.", idiomatic: "Yuwen Tai promoted Mu to Governor of the Capital District." },
  { zh: "侯景與東魏慕容紹宗相持數月，景食盡，司馬世雲降於紹宗。", literal: "Hou Jing and Eastern Wei's Murong Shaozong faced each other for months; Jing's food was exhausted, and Sima Shiyun surrendered to Shaozong.", idiomatic: "Hou Jing and Murong Shaozong of Eastern Wei faced each other for months; Hou Jing's food was exhausted, and Sima Shiyun surrendered to Shaozong." },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
